function startLiveUpdates(){if(LIVE_EVENT_SOURCE||typeof EventSource!=='function')return;try{const source=new EventSource('/api/bi/live-events');source.addEventListener('ready',message=>{try{const ready=JSON.parse(message.data||'{}'),at=ready?.live?.lastOrderAt;LIVE_LAST_ORDER_AT=newestStamp(LIVE_LAST_ORDER_AT,at);if(at)queueLiveRefresh({kind:'order',receivedAt:at,sections:LIVE_ORDER_SECTIONS});else render()}catch{}});source.addEventListener('live-update',message=>{try{queueLiveRefresh(JSON.parse(message.data||'{}'))}catch{}});source.onerror=()=>{};LIVE_EVENT_SOURCE=source;window.addEventListener('pagehide',()=>source.close(),{once:true})}catch(e){console.warn('BI 实时事件流暂不可用，已保留五分钟兜底',e)}}

function sectionExpectedAt(){return D.__sections?.generatedAt||D.generatedAt||genAt()||''}
function sectionNeedsAttention(n){const st=SS[n]||{};return !!(st.stale||st.refreshing||st.refreshError)}
function sectionNeedsBanner(n){const st=SS[n]||{},expected=String(st.coreGeneratedAt||sectionExpectedAt()),actual=String(st.generatedAt||''),loading=st.status==='loading',slow=loading&&st.startedAt&&Date.now()-st.startedAt>LOAD_HINT_MS;return !!(st.pendingSection||(loading&&(st.refreshing||slow))||(st.stale&&expected&&actual&&actual!==expected)||(!st.refreshing&&st.refreshError))}
function staleTip(n){const s=SS[n]||{};if(!sectionNeedsAttention(n))return'';return `${SL[n]||n} 当前显示缓存数据
缓存生成：${fmtStamp(s.generatedAt)}
缓存写入：${fmtStamp(s.cachedAt)}
页面最新：${fmtStamp(s.coreGeneratedAt||sectionExpectedAt())}
${s.refreshing?'后台正在生成最新 section；完成后页面会自动更新。':'系统只会进行有限次自动重试；耗尽后请点击强制刷新手动重试。'}${s.refreshError?'\n最近一次刷新失败：'+s.refreshError:''}`}
function sectionFailureNotice(ns){const failed=(ns||[]).filter(n=>SS[n]?.status==='error');if(!failed.length)return'';const rows=failed.map(n=>{const st=SS[n]||{};return`<li><b>${H(SL[n]||n)}</b>：${H(st.error||'请求失败')} <button type="button" class="btn" data-load="${H(n)}">重试</button></li>`}).join('');return`<section class="section-failure-notice" role="alert" aria-live="assertive"><strong>部分经营数据暂时不可用，受影响 KPI 不会显示为 0</strong><p>请重试对应数据源；恢复前请勿据此做经营判断。</p><ul>${rows}</ul></section>`}
function staleNotice(ns){const xs=(ns||[]).filter(sectionNeedsBanner);if(!xs.length)return'';const working=xs.some(n=>SS[n]?.refreshing||SS[n]?.status==='loading');const rows=xs.map(n=>{const st=SS[n]||{},isWorking=st.refreshing||st.status==='loading',state=isWorking?'缓存正在刷新':st.stale?'缓存兜底':'刷新异常';const hasCache=!!(st.cachedAt||st.generatedAt);const detail=hasCache?`${SL[n]||n}：缓存写入 ${fmtStamp(st.cachedAt||st.generatedAt)}；页面最新 ${fmtStamp(st.coreGeneratedAt||sectionExpectedAt())}`:`${SL[n]||n}：正在生成首份数据，完成后页面会自动更新`;const err=!isWorking&&st.refreshError?`<em>${H(st.refreshError)}</em>`:'';const action=isWorking?`<button type="button" class="btn" data-reset-cache="${H(n)}">重置缓存</button>`:`<button type="button" class="btn" data-load="${H(n)}">强制刷新最新</button>`;return`<div class="stale-line"><span><b>${H(state)}</b>${H(detail)}${err}</span>${action}</div>`}).join('');return`<div class="stale-notice" role="status" aria-live="polite"><strong>${working?'缓存正在刷新':'⚠ 部分数据仍在使用上一份完整缓存'}</strong><p>${working?'页面会先显示可用缓存并自动更新；如果长时间没有完成，可以重置当前页面缓存后重新读取。':'系统只进行有限次自动重试；耗尽后请手动重试。恢复前页面不会把缺失数据冒充为 0。'}</p>${rows}</div>`}
function chips(ns){return'<div class="sects">'+(ns||[]).map(n=>{const st=SS[n]||{},s=st.status||'idle',c=st.refreshing?'refreshing':st.stale?'stale':s==='ok'?'ok':s==='loading'?'loading-chip':s==='error'?'bad':'';const label=st.refreshing?'刷新中':st.stale?'缓存兜底':s==='ok'?'已就绪':s==='loading'?'加载中':s==='error'?'失败':'未请求';return`<span class="${c}" title="${H(sectionNeedsAttention(n)?staleTip(n):(st.error||''))}">${H(SL[n]||n)} · ${label}</span>`}).join('')+'</div>'}


function wait(n,t='正在从云端 section API 加载数据…'){const s=SS[n]||{};if(s.status==='error')return`<div class="error" role="alert"><b>${H(SL[n]||n)} 加载失败</b><br>${H(s.error)}<p><button type="button" class="btn" data-load="${H(n)}">重试</button></p></div>`;load(n,true);const slow=s.startedAt&&Date.now()-s.startedAt>LOAD_HINT_MS;return`<div class="loading" role="status" aria-live="polite"><span class="spin" aria-hidden="true"></span><span>${H(t)}${slow?'<small>若正在刷新新 section，会先尝试读取可用缓存；旧缓存会在页面顶部明确标黄提示，不会静默冒充最新。</small>':''}</span></div>`}

