[...A(D.rankings?.dailyStores),...A(D.rankings?.dailyStoreProducts),...A(D.rankings?.dailyProducts),...A(D.productSalesDaily),...A(D.homeTrafficDaily),...A(D.homeProfitSummary?.dailyScopes),...A(D.profit?.dailyStoreProducts),...A(D.productProfit?.rows),...A(D.afterSales),...A(D.orders),...A(D.productTrafficDaily),...A(D.inventoryTrend),...A(D.inventoryDepletion?.visibleTrend)].forEach(r=>{const d=dt(r);if(d)ds.push(d)});
