function salesSummary(){const rows=sales();const prows=psales();const productRows=prows.length?prows:rows;const active=(fn)=>{const xs=uniq(productRows.filter(r=>fn(r)>0).map(pkey));return xs.length||null};const net=sumFirst(rows,['sales_sar','net_revenue_sar','known_net_revenue_sar']);const gross=rows.reduce((a,r)=>a+grossSales(r),0);const qty=rows.reduce((a,r)=>a+netQty(r),0);const gqty=rows.reduce((a,r)=>a+grossQty(r),0);return{rows,productRows,net,gross,ord:rows.reduce((a,r)=>a+netOrders(r),0),gord:rows.reduce((a,r)=>a+grossOrders(r),0),qty,gqty,active:active(netQty),gactive:active(grossQty),avg:qty?net/qty:0}}
function salesPaymentRows(){const productScoped=Boolean(String(S.q||'').trim());const rows=productScoped&&A(D.rankings?.dailyStoreProductPaymentSummary).length?D.rankings.dailyStoreProductPaymentSummary:D.rankings?.dailyPaymentSummary;return F(rows||[])}
