function hprofit(){const productScoped=Boolean(String(S.q||'').trim());if(productScoped)return profits();const rows=A(D.homeProfitSummary?.dailyScopes),liveDate=ISO(D.liveSalesToday?.date),liveRows=A(D.liveSalesToday?.profitStoreRows),useLive=Boolean(liveDate&&liveRows.length&&(!S.start||liveDate>=S.start)&&(!S.end||liveDate<=S.end)),set=scopeStores(),all=S.scope==='ALL',owner=String(S.scope).startsWith('OWNER:');const historical=rows.filter(r=>{const d=ISO(r.date);if(useLive&&d===liveDate)return false;if(S.start&&d<S.start)return false;if(S.end&&d>S.end)return false;const sv=String(r.scope_value||'').toUpperCase();if(all)return sv===''||sv==='ALL';if(owner)return set.has(sv);return sv===String(S.scope).toUpperCase()});if(!useLive)return historical;return[...historical,...liveRows.filter(r=>set.has(sk(r)))]}

