const TREND_METRICS={sales:{label:'成交额',money:true},quantity:{label:'销量'},returns:{label:'售后'},profit:{label:'利润',money:true},traffic:{label:'流量'},inventory:{label:'库存'}};
function trendMetricButtons(){return`<div class="trend-toggle" role="group" aria-label="趋势指标">${Object.entries(TREND_METRICS).map(([k,m])=>`<button type="button" class="${S.trendMetric===k?'active':''}" data-trend-metric="${H(k)}" aria-pressed="${S.trendMetric===k?'true':'false'}">${H(m.label)}</button>`).join('')}</div>`}
function bucketLabel(id,kind){return kind==='month'?id:id}
function bucket(map,id,kind){const row=map.get(id)||{id,label:bucketLabel(id,kind)};map.set(id,row);return row}
function rowsFromMap(map){return Array.from(map.values()).sort((a,b)=>String(a.id).localeCompare(String(b.id)))}
function addTrend(map,kind,date,vals){if(!date)return;const id=kind==='month'?monthId(date):date;const r=bucket(map,id,kind);Object.entries(vals).forEach(([k,v])=>r[k]=N(r[k])+N(v))}
function buildTrendSeries(kind,metric=S.trendMetric){const map=new Map();if(metric==='sales'||metric==='quantity'){for(const r of sales()){const d=dt(r);addTrend(map,kind,d,metric==='sales'?{net:netSales(r),gross:grossSales(r)}:{net:netQty(r),gross:grossQty(r)})}return{series:rowsFromMap(map),lines:[{key:'net',label:metric==='sales'?'净成交额':'净销量',color:metric==='sales'?'#10b981':'#60a5fa'},{key:'gross',label:metric==='sales'?'总成交额':'总销量',color:metric==='sales'?'#f59e0b':'#a78bfa'}],note:'按当前店铺/负责人、货号和日期筛选重算。'}}
if(metric==='returns'){for(const r of orderCreatedReturns()){const d=returnDate(r,'order');addTrend(map,kind,d,{order:1})}for(const r of returns()){const d=returnDate(r,'request');addTrend(map,kind,d,{request:1})}return{series:rowsFromMap(map),lines:[{key:'request',label:'售后申请时间',color:'#ef4444'},{key:'order',label:'订单创建时间',color:'#f97316'}],note:'两条线都来自售后明细：申请时间看本期新申请售后，订单创建时间看本期创建订单后续发生的售后。'}}
if(metric==='profit'){for(const r of hprofit()){const d=dt(r);addTrend(map,kind,d,{realized:profitAmountLoss(r),risk:profitRiskAdjusted(r)})}return{series:rowsFromMap(map),lines:[{key:'realized',label:'已落定利润',color:'#14b8a6'},{key:'risk',label:'风险调整后利润',color:'#f97316'}],note:'两条线都含仓储费；未落定售后只进入风险线，不提前冲减已落定利润。'}}
if(metric==='traffic'){const tr=trafficSummary(false);for(const r of tr.rows){const d=dt(r);addTrend(map,kind,d,{eps:firstNum(r,['eps_uv','exposure_uv','exposure_cnt','impressions']),uv:firstNum(r,['goods_uv','uv','visitor_cnt','visitors']),sale:firstNum(r,['sale_cnt','pay_order_cnt','quantity'])})}return{series:rowsFromMap(map),lines:[{key:'eps',label:'曝光量',color:'#06b6d4'},{key:'uv',label:'访客量',color:'#3b82f6'},{key:'sale',label:'成交件数',color:'#8b5cf6'}],rangeText:tr.rangeText,note:(tr.effectiveShifted?`已按流量最新可用区间 ${tr.rangeText} 展示。`:'')+'绝对量同轴展示；点击率/支付率留在顶部流量卡。'}}
if(metric==='inventory'){const latestByMonth=new Map();for(const r of invTrendLoose()){const d=dt(r);if(!d)continue;const id=kind==='month'?monthId(d):d;const row=latestByMonth.get(id)||{id,label:id,date:''};if(!row.date||d>=row.date){row.date=d;row.usable=firstNum(r,['usable_inventory','platform_display_stock','available_qty']);row.total=firstNum(r,['inventory_quantity','total_inventory','platform_total_stock']);row.locked=firstNum(r,['order_locked_quantity','pay_locked_quantity','locked_inventory'])}latestByMonth.set(id,row)}return{series:rowsFromMap(latestByMonth),lines:[{key:'usable',label:'可售展示库存',color:'#14b8a6'},{key:'total',label:'总展示库存',color:'#60a5fa'},{key:'locked',label:'锁定库存',color:'#f59e0b'}],note:(kind==='month'?'月图取每月最新快照，不累加库存。':'来自前台展示库存每日快照。')}}
return{series:[],lines:[],note:''}}
function trendValueText(v,metric=S.trendMetric){const meta=TREND_METRICS[metric]||{};return meta.money?money(v):M(v)}
function niceCeil(v){const n=Math.abs(N(v));if(n<=10)return 10;const p=Math.pow(10,Math.floor(Math.log10(n)));return Math.ceil(n/p)*p}
function dataTip(v){return H(v).replace(/\n/g,'&#10;')}
function adaptivePriceScale(values,maxBins=8){
const prices=A(values).map(N).filter(v=>v>0),minPrice=prices.length?Math.min(...prices):0,maxPrice=prices.length?Math.max(...prices):0,uniquePriceCount=new Set(prices.map(v=>v.toFixed(6))).size;
if(!prices.length)return{prices:[],minPrice:0,maxPrice:0,span:0,binCount:0,binWidth:0,edges:[],bins:[]};
if(maxPrice===minPrice||uniquePriceCount===1)return{prices,minPrice,maxPrice,span:0,binCount:1,binWidth:0,edges:[minPrice],bins:[{index:0,lo:minPrice,hi:maxPrice}]};
const binCount=Math.max(2,Math.min(maxBins,uniquePriceCount,Math.ceil(Math.sqrt(prices.length)))),span=maxPrice-minPrice,binWidth=span/binCount;
const edges=Array.from({length:binCount+1},(_,i)=>i===binCount?maxPrice:minPrice+binWidth*i);
const bins=Array.from({length:binCount},(_,i)=>({index:i,lo:edges[i],hi:edges[i+1]}));
return{prices,minPrice,maxPrice,span,binCount,binWidth,edges,bins};
}
function adaptivePriceBinIndex(value,scale){if(!scale?.binCount)return-1;if(scale.binCount===1||scale.binWidth<=0)return 0;return Math.min(scale.binCount-1,Math.max(0,Math.floor((N(value)-scale.minPrice)/scale.binWidth)))}
function priceBandText(bin,unit=true){if(!bin)return'—';const range=Math.abs(N(bin.hi)-N(bin.lo))<.005?M2(bin.lo):`${M2(bin.lo)}-${M2(bin.hi)}`;return unit?range+' SAR':range}
function priceDistData(){
const q=String(S.q||'').trim();if(!q)return{needsProduct:true,bins:[],rows:[]};
const rows=(psales().length?psales():sales()).map(r=>{const qty=netQty(r),salesValue=netSales(r),orders=netOrders(r),avg=qty?salesValue/qty:0;return{row:r,avg,qty,sales:salesValue,orders}}).filter(r=>r.avg>0&&r.qty>0);
if(!rows.length)return{needsProduct:false,bins:[],rows:[]};
const totalSales=rows.reduce((a,r)=>a+r.sales,0),totalQty=rows.reduce((a,r)=>a+r.qty,0),totalOrders=rows.reduce((a,r)=>a+r.orders,0);
const scale=adaptivePriceScale(rows.map(r=>r.avg)),bins=scale.bins.map(b=>({...b,sales:0,qty:0,orders:0,rows:0}));
for(const r of rows){const b=bins[adaptivePriceBinIndex(r.avg,scale)];if(!b)continue;b.sales+=r.sales;b.qty+=r.qty;b.orders+=r.orders;b.rows+=1}
const activeBins=bins.filter(b=>b.qty>0),best=activeBins.slice().sort((a,b)=>b.qty-a.qty||b.orders-a.orders)[0]||null;
return{needsProduct:false,rows,bins:activeBins,totalSales,totalQty,totalOrders,avg:totalQty?totalSales/totalQty:0,minPrice:scale.minPrice,maxPrice:scale.maxPrice,binCount:scale.binCount,binWidth:scale.binWidth,best,label:rows[0]?prod(rows[0].row):q};
}

function priceDistPanel(){
const data=priceDistData();
if(data.needsProduct)return`<section class="panel price-dist-panel"><h4>单货号成交价格分布</h4><p class="sub">${H(selectedRangeText())} · 用于报活动前判断真实成交价带</p><div class="empty price-dist-empty">请在搜索框选择或输入货号，查看该货号的成交价格分布</div></section>`;
if(sourceLoading('homeRankings',data.rows))return`<section class="panel price-dist-panel"><h4>单货号成交价格分布</h4><p class="sub">${H(SL.homeRankings)} 加载中</p><div class="empty">正在加载销售明细，加载完成后自动刷新本图。</div></section>`;
if(!data.bins.length)return`<section class="panel price-dist-panel"><h4>单货号成交价格分布</h4><p class="sub">${H(homeScopeSubtitle())} · ${H(selectedRangeText())}</p><div class="empty">当前货号没有可计算成交均价的销售明细。</div></section>`;
const W=760,chartH=330,padL=58,padR=22,padT=24,padB=58,plotW=W-padL-padR,plotH=chartH-padT-padB;
const maxQty=Math.max(...data.bins.map(b=>b.qty),1),barGap=8,barW=Math.max(12,(plotW-barGap*(data.bins.length-1))/data.bins.length);
const yFor=v=>padT+plotH-(N(v)/maxQty)*plotH;
const ticks=[0,maxQty*.25,maxQty*.5,maxQty*.75,maxQty];
const grid=ticks.map(v=>`<line class="grid-line" x1="${padL}" y1="${yFor(v).toFixed(1)}" x2="${W-padR}" y2="${yFor(v).toFixed(1)}"></line><text class="axis-tick" text-anchor="end" x="${padL-8}" y="${(yFor(v)+4).toFixed(1)}">${H(M(v))}</text>`).join('');
const bars=data.bins.map((b,i)=>{const x=padL+i*(barW+barGap),y=yFor(b.qty),barHeight=Math.max(2,plotH-(y-padT)),hot=b===data.best,avg=b.qty?b.sales/b.qty:0,pct=data.totalQty?b.qty/data.totalQty:0,band=priceBandText(b);const tip=dataTip(`${band}\n销量：${M(b.qty)} 件\n订单：${M(b.orders)} 单\n占总销量：${PCT(pct)}\n段内均价：${M2(avg)} SAR`);return`<g class="price-dist-bar ${hot?'hot':''}"><rect data-tip="${tip}" x="${x.toFixed(1)}" y="${(padT+plotH-barHeight).toFixed(1)}" width="${barW.toFixed(1)}" height="${barHeight.toFixed(1)}" rx="8"></rect><text class="price-dist-value" x="${(x+barW/2).toFixed(1)}" y="${Math.max(14,padT+plotH-barHeight-6).toFixed(1)}" text-anchor="middle">${H(M(b.qty))}</text><text class="axis-tick price-dist-x" x="${(x+barW/2).toFixed(1)}" y="${(chartH-padB+19).toFixed(1)}" text-anchor="middle">${H(priceBandText(b,false))}</text></g>`}).join('');
const best=data.best,priceRange=`${M2(data.minPrice)}~${M2(data.maxPrice)} SAR`,bestText=priceBandText(best);
return`<section class="panel price-dist-panel"><h4>单货号成交价格分布</h4><p class="sub">${H(homeScopeSubtitle())} · ${H(selectedRangeText())} · 按每行净成交额/净销量计算均价，按真实最低/最高价自适应 ${H(M(data.binCount))} 段</p>
<div class="price-dist-kpis">
<span><em>整体均价</em><b>${H(M2(data.avg))}</b><small>SAR</small></span>
<span class="hot"><em>最畅销价格</em><b>${H(bestText)}</b><small>${best?M(best.qty)+'件 / '+M(best.orders)+'单':'—'}</small></span>
<span><em>价格区间</em><b>${H(priceRange)}</b></span>
<span><em>总销量</em><b>${H(M(data.totalQty))}</b><small>件</small></span>
<span><em>总订单</em><b>${H(M(data.totalOrders))}</b><small>单</small></span>
</div>
<div class="price-dist-wrap"><svg viewBox="0 0 ${W} ${chartH}" role="img" aria-label="单货号成交价格分布柱状图">
<defs><linearGradient id="priceDistBar" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#94a3b8"/><stop offset="1" stop-color="#cbd5e1"/></linearGradient><linearGradient id="priceDistHot" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#10b981"/><stop offset="1" stop-color="#34d399"/></linearGradient></defs>
<rect class="plot-band" x="${padL}" y="${padT}" width="${plotW}" height="${plotH}" rx="14"/>
${grid}<line class="axis-line" x1="${padL}" y1="${padT}" x2="${padL}" y2="${chartH-padB}"/><line class="axis-line" x1="${padL}" y1="${chartH-padB}" x2="${W-padR}" y2="${chartH-padB}"/>
${bars}
<text class="axis-label" x="${(padL+plotW/2).toFixed(1)}" y="${(chartH-10).toFixed(1)}" text-anchor="middle">成交均价价格段 (SAR)</text>
<text class="axis-label" x="14" y="${(padT+plotH/2).toFixed(1)}" text-anchor="middle" transform="rotate(-90 14 ${(padT+plotH/2).toFixed(1)})">销量 (件)</text>
</svg></div>
<div class="chart-legend price-dist-legend"><span><i style="--c:#10b981"></i>最畅销价格段</span><span><i style="--c:#94a3b8"></i>其他成交价格段</span><span class="price-dist-summary">样本 ${H(M(data.rows.length))} 行 · 净成交额 ${H(money(data.totalSales))}</span></div></section>`;
}


function priceScatterRows(){return A(D.priceScatter).filter(r=>{const price=N(r?.unit_price_sar),qty=N(r?.quantity);return price>0&&qty>0&&inSelectedRange(r?.created_date||r?.order_create_time)&&scopeSearchOk(r)})}
function priceScatterSample(rows,scale,limit=5000){if(rows.length<=limit)return rows;const byBin=new Map();for(const r of rows){const key=adaptivePriceBinIndex(r.unit_price_sar,scale);if(key<0)continue;if(!byBin.has(key))byBin.set(key,[]);byBin.get(key).push(r)}const perBin=Math.max(1,Math.floor(limit/Math.max(1,byBin.size))),sample=[];for(const xs of byBin.values()){const step=Math.max(1,Math.ceil(xs.length/perBin));for(let i=0;i<xs.length&&sample.length<limit;i+=step)sample.push(xs[i])}return sample}
function priceScatterPanel(){
if(!A(D.priceScatter).length&&SS.priceScatter?.status!=='ok')return`<section class="panel price-scatter-panel"><h4>订单成交价散点图</h4><p class="sub">${H(selectedRangeText())} · 每个点是一笔订单商品行</p><div class="empty price-scatter-empty">正在加载订单级散点数据…</div></section>`;
const rows=priceScatterRows();
if(!rows.length)return`<section class="panel price-scatter-panel"><h4>订单成交价散点图</h4><p class="sub">${H(homeScopeSubtitle())} · ${H(selectedRangeText())}</p><div class="empty price-scatter-empty">当前筛选条件下没有订单级数据</div></section>`;
const scale=adaptivePriceScale(rows.map(r=>r.unit_price_sar)),minPrice=scale.minPrice,maxPrice=scale.maxPrice,bins=scale.bins.map(b=>({...b,qty:0,rows:0}));
let totalSales=0,totalQty=0;for(const r of rows){const qty=N(r.quantity);totalSales+=N(r.sales_sar);totalQty+=qty;const b=bins[adaptivePriceBinIndex(r.unit_price_sar,scale)];if(b){b.qty+=qty;b.rows+=1}}
const activeBins=bins.filter(b=>b.qty>0),best=activeBins.slice().sort((a,b)=>b.qty-a.qty||b.rows-a.rows)[0]||null,sampled=priceScatterSample(rows,scale,5000);
const w=1280,h=360,padL=72,padR=28,padT=28,padB=54,plotW=w-padL-padR,plotH=h-padT-padB;
const dateValues=rows.map(r=>ISO(r.created_date||r.order_create_time)).filter(Boolean).sort(),startDate=S.start||dateValues[0]||'',endDate=S.end||dateValues.at(-1)||startDate;
const startMs=(parseDateOnly(startDate)||parseDateOnly(dateValues[0])||new Date()).getTime(),endMs=(parseDateOnly(endDate)||parseDateOnly(dateValues.at(-1))||new Date()).getTime(),sameDay=!(Number.isFinite(startMs)&&Number.isFinite(endMs))||startMs===endMs;
const xFor=r=>{if(sameDay)return padL+plotW/2;const d=parseDateOnly(r.created_date||r.order_create_time);const ms=d?d.getTime():startMs;return padL+Math.max(0,Math.min(1,(ms-startMs)/(endMs-startMs)))*plotW};
const yFor=v=>scale.span>0?padT+plotH-(Math.max(0,Math.min(1,(N(v)-minPrice)/scale.span)))*plotH:padT+plotH/2;
const yTicks=scale.edges.length?scale.edges:[minPrice],grid=yTicks.map(v=>`<line class="grid-line" x1="${padL}" y1="${yFor(v).toFixed(1)}" x2="${w-padR}" y2="${yFor(v).toFixed(1)}"></line><text class="axis-tick" text-anchor="end" x="${padL-8}" y="${(yFor(v)+4).toFixed(1)}">${H(M2(v))}</text>`).join('');
const axisDates=sameDay?[startDate]:[startDate,addDateDays(startDate,Math.round((endMs-startMs)/86400000/2)),endDate].filter(Boolean),dateAxis=axisDates.map(d=>{const ms=(parseDateOnly(d)||new Date(startMs)).getTime(),x=sameDay?padL+plotW/2:padL+Math.max(0,Math.min(1,(ms-startMs)/(endMs-startMs)))*plotW;return`<text class="axis-tick price-scatter-axis" text-anchor="middle" x="${x.toFixed(1)}" y="${h-18}">${H(d)}</text>`}).join('');
const hasProduct=!!String(S.q||'').trim(),storeColor=r=>hasProduct?'#6366f1':(ownByStore.get(sk(r))?.color||'#6366f1'),radius=sampled.length>3500?2.4:3,opacity=sampled.length>3500?.46:.6;
const dots=sampled.map(r=>{const date=ISO(r.created_date||r.order_create_time),store=sk(r),product=pkey(r)||prod(r),tip=dataTip(`日期：${date||'—'}\n店铺：${storeDisplayName(store)||'—'}\n货号：${product||'—'}\n单价：${M2(r.unit_price_sar)} SAR\n数量：${M(r.quantity)}\n金额：${M2(r.sales_sar)} SAR`);return`<circle class="price-scatter-dot" data-tip="${tip}" tabindex="${sampled.length<=300?'0':'-1'}" role="img" aria-label="${tip}" cx="${xFor(r).toFixed(1)}" cy="${yFor(r.unit_price_sar).toFixed(1)}" r="${radius}" fill="${H(storeColor(r))}" opacity="${opacity}"></circle>`}).join('');
const priceRange=`${M2(minPrice)}~${M2(maxPrice)}`,bestText=priceBandText(best),sampleNote=sampled.length<rows.length?` · 已抽样 ${M(sampled.length)} / ${M(rows.length)} 点`:'';
const legendStores=hasProduct?[]:uniq(sampled.map(sk)).slice(0,10);
return`<section class="panel price-scatter-panel"><h4>订单成交价散点图</h4><p class="sub">${H(homeScopeSubtitle())} · ${H(selectedRangeText())} · 点=订单商品行，纵轴从真实最低价到最高价，并自适应分为 ${H(M(scale.binCount))} 段${H(sampleNote)}</p>
<div class="price-scatter-kpis">
<span><em>订单行数</em><b>${H(M(rows.length))}</b><small>当前筛选</small></span>
<span><em>价格区间</em><b>${H(priceRange)}</b><small>SAR</small></span>
<span><em>加权均价</em><b>${H(M2(totalQty?totalSales/totalQty:0))}</b><small>SAR</small></span>
<span class="hot"><em>最畅销价格段</em><b>${H(bestText)}</b><small>${best?M(best.qty)+'件 / '+M(best.rows)+'行':'—'}</small></span>
</div>
<div class="price-scatter-wrap"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="订单成交价散点图">
<rect class="plot-band" x="${padL}" y="${padT}" width="${plotW}" height="${plotH}" rx="14"></rect>
${grid}<line class="axis-line" x1="${padL}" y1="${padT}" x2="${padL}" y2="${h-padB}"></line><line class="axis-line" x1="${padL}" y1="${h-padB}" x2="${w-padR}" y2="${h-padB}"></line>
${dots}${dateAxis}
<text class="axis-label price-scatter-axis" x="${(padL+plotW/2).toFixed(1)}" y="${h-4}" text-anchor="middle">订单日期</text>
<text class="axis-label price-scatter-axis" x="14" y="${(padT+plotH/2).toFixed(1)}" text-anchor="middle" transform="rotate(-90 14 ${(padT+plotH/2).toFixed(1)})">单件成交价 (SAR)</text>
</svg></div>
<details class="chart-readable-details"><summary>查看可读散点明细（${H(M(Math.min(sampled.length,100)))} / ${H(M(rows.length))} 行）</summary><p>每行对应一个可见散点；样本超过 100 行时仅列前 100 行，完整明细请到订单中心筛选。</p><div class="table-wrap chart-readable-table" role="region" aria-label="订单成交价散点可读明细"><table><thead><tr><th>日期</th><th>店铺</th><th>货号</th><th class="num">单价</th><th class="num">数量</th><th class="num">金额</th></tr></thead><tbody>${sampled.slice(0,100).map(r=>`<tr><td>${H(ISO(r.created_date||r.order_create_time)||'—')}</td><td>${H(storeDisplayName(sk(r))||'—')}</td><td>${H(pkey(r)||prod(r)||'—')}</td><td class="num">${H(M2(r.unit_price_sar))} SAR</td><td class="num">${H(M(r.quantity))}</td><td class="num">${H(M2(r.sales_sar))} SAR</td></tr>`).join('')}</tbody></table></div></details>
<div class="chart-legend price-scatter-legend">${hasProduct?'<span><i style="--c:#6366f1"></i>当前货号</span>':legendStores.map(k=>`<span><i style="--c:${H(ownByStore.get(k)?.color||'#6366f1')}"></i>${H(k)}</span>`).join('')}${legendStores.length>=10?'<span>…</span>':''}</div></section>`;
}

function lineChart(kind,metric=S.trendMetric){
const built=buildTrendSeries(kind,metric),series=built.series||[],lines=built.lines||[];
const meta=TREND_METRICS[metric]||{};
if(!series.length||!lines.length)return`<div class="empty">当前时间段 ${H(selectedRangeText())} 暂无${H(meta.label||metric)}趋势数据。</div>`;
const keys=lines.map(x=>x.key),colors=Object.fromEntries(lines.map(x=>[x.key,x.color])),labels=Object.fromEntries(lines.map(x=>[x.key,x.label]));
const overlay=(metric==='sales'||metric==='quantity')&&keys.includes('net')&&keys.includes('gross');
const canOverlay=r=>{const net=N(r.net),gross=N(r.gross);return gross>=0&&net>=0&&net<=gross};
const vals=series.flatMap(r=>keys.map(k=>N(r[k])));
const maxRaw=Math.max(1,...vals),minRaw=Math.min(0,...vals);
const max=niceCeil(maxRaw),min=minRaw<0?-niceCeil(Math.abs(minRaw)):0,span=Math.max(1,max-min);
const w=1280,h=306,padL=72,padR=28,padT=28,padB=54,plotW=w-padL-padR,plotH=h-padT-padB;
const yFor=v=>padT+(1-((N(v)-min)/span))*plotH,zeroY=yFor(0);
const ticks=[min,min+span*.25,min+span*.5,min+span*.75,max];
const grid=ticks.map(v=>`<line class="grid-line" x1="${padL}" y1="${yFor(v).toFixed(1)}" x2="${w-padR}" y2="${yFor(v).toFixed(1)}"></line><text class="axis" text-anchor="end" x="${padL-8}" y="${(yFor(v)+4).toFixed(1)}">${H(compact(v))}</text>`).join('');
const groupW=plotW/Math.max(1,series.length),dense=groupW<keys.length*7,innerGap=dense?0:4,groupInner=Math.max(1,groupW*(dense?0.88:0.72));
const groupedBarW=Math.max(dense?0.9:2,Math.min(28,(groupInner-innerGap*(keys.length-1))/Math.max(1,keys.length)));
const overlayTotalW=Math.max(dense?1.2:3,Math.min(34,groupW*(dense?0.74:0.52)));
const overlayNetW=Math.max(dense?0.85:2,overlayTotalW*.56);
const groupX=i=>padL+i*groupW+groupW/2;
const groupedBarX=(i,ki)=>groupX(i)-(groupedBarW*keys.length+innerGap*(keys.length-1))/2+ki*(groupedBarW+innerGap);
const gid=k=>`trend-${kind}-${metric}-${k}`.replace(/[^a-z0-9_-]/gi,'-');
const defs=`<defs>${lines.map(l=>`<linearGradient id="${H(gid(l.key))}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${H(l.color)}" stop-opacity=".96"></stop><stop offset="1" stop-color="${H(l.color)}" stop-opacity=".48"></stop></linearGradient>`).join('')}</defs>`;
const rectFor=(klass,x,width,v,fill,tip)=>{const y=yFor(v),top=Math.min(y,zeroY),height=Math.abs(zeroY-y),rx=Math.min(6,Math.max(1,width/2));return`<rect class="trend-bar ${klass}" data-tip="${tip}" x="${x.toFixed(1)}" y="${top.toFixed(1)}" width="${width.toFixed(1)}" height="${height.toFixed(1)}" rx="${rx.toFixed(1)}" fill="${fill}"></rect>`};
const overlayDetail=r=>{const gross=N(r.gross),net=N(r.net),diff=gross-net;return`${labels.gross}：${trendValueText(gross,metric)}\n${labels.net}：${trendValueText(net,metric)}\n反转/扣减：${trendValueText(diff,metric)}${canOverlay(r)?'':'\n口径关系异常，已并列显示'}`};
const bars=overlay?series.map((r,i)=>{const tip=dataTip(r.label+'\n'+overlayDetail(r));if(canOverlay(r)){const cx=groupX(i),gross=N(r.gross),net=N(r.net);return rectFor('trend-bar-total',cx-overlayTotalW/2,overlayTotalW,gross,`url(#${H(gid('gross'))})`,tip)+rectFor('trend-bar-net',cx-overlayNetW/2,overlayNetW,net,`url(#${H(gid('net'))})`,tip)}return keys.map((k,ki)=>rectFor('trend-bar-fallback',groupedBarX(i,ki),groupedBarW,N(r[k]),`url(#${H(gid(k))})`,tip)).join('')}).join(''):keys.map((k,ki)=>series.map((r,i)=>{const tip=dataTip(labels[k]+' · '+r.label+'\n'+trendValueText(r[k],metric));return rectFor('',groupedBarX(i,ki),groupedBarW,N(r[k]),`url(#${H(gid(k))})`,tip)}).join('')).join('');
const every=series.length<=7?1:Math.ceil(series.length/(kind==='month'?7:6));
const valueLabels=overlay?series.map((r,i)=>{if(!(i===0||i===series.length-1||i%every===0))return'';const v=N(r.net);if(!v&&i!==0&&i!==series.length-1)return'';const x=groupX(i),y=yFor(v),anchor=i===0?'start':i===series.length-1?'end':'middle';return`<text class="value-label bar-value-label" text-anchor="${anchor}" x="${x.toFixed(1)}" y="${Math.max(14,y-7).toFixed(1)}" fill="${colors.net}">${H(compact(v))}</text>`}).join(''):keys.map((k,ki)=>series.map((r,i)=>{if(!(i===0||i===series.length-1||i%every===0))return'';const v=N(r[k]);if(!v&&i!==0&&i!==series.length-1)return'';const x=groupedBarX(i,ki)+groupedBarW/2,y=yFor(v),positive=v>=0,ty=positive?Math.max(14,y-7-ki*12):Math.min(h-padB+20,y+14+ki*12);const anchor=i===0?'start':i===series.length-1?'end':'middle';return`<text class="value-label bar-value-label" text-anchor="${anchor}" x="${x.toFixed(1)}" y="${ty.toFixed(1)}" fill="${colors[k]}">${H(compact(v))}</text>`}).join('')).join('');
const hitW=Math.max(10,Math.min(120,groupW*.92));
const hits=series.map((r,i)=>{const x=Math.max(padL,Math.min(w-padR-hitW,groupX(i)-hitW/2));const detail=overlay?overlayDetail(r):keys.map(k=>labels[k]+'：'+trendValueText(r[k],metric)).join('\n');const tip=dataTip(r.label+'\n'+detail);return`<rect class="chart-hit" data-tip="${tip}" tabindex="0" role="img" aria-label="${tip}" x="${x.toFixed(1)}" y="${padT}" width="${hitW.toFixed(1)}" height="${plotH}"></rect>`}).join('');
const axisEvery=Math.ceil(series.length/6);
const axis=series.map((r,i)=>(series.length<=8||i===0||i===series.length-1||i%axisEvery===0)?`<text class="axis" text-anchor="${i===0?'start':i===series.length-1?'end':'middle'}" x="${groupX(i).toFixed(1)}" y="${h-10}">${H(r.label)}</text>`:'').join('');
const latestRow=series.at(-1)||{};
const summedRow=series.reduce((a,r)=>{keys.forEach(k=>a[k]=N(a[k])+N(r[k]));return a},{});
const summaryRow=metric==='inventory'?latestRow:summedRow;
const summaryValue=k=>H(trendValueText(summaryRow[k]||0,metric));
const legend=overlay?`<span class="legend-net"><i style="--c:${colors.net}"></i>${H(labels.net)}：${summaryValue('net')}</span><span class="legend-total"><i style="--c:${colors.gross}"></i>${H(labels.gross)}：${summaryValue('gross')}</span><span class="legend-diff"><i style="--c:#9b8b77"></i>反转/扣减：${H(trendValueText(N(summaryRow.gross)-N(summaryRow.net),metric))}</span>`:keys.map(k=>`<span><i style="--c:${colors[k]}"></i>${H(labels[k])}：${summaryValue(k)}</span>`).join('');
return`<div class="line-chart bar-chart${overlay?' overlay-bar-chart':''}"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${H((kind==='month'?'月':'日')+(meta.label||metric)+'柱状趋势')}">${defs}<rect class="plot-band" x="${padL}" y="${padT}" width="${plotW}" height="${plotH}" rx="14"></rect>${grid}<line class="axis-line" x1="${padL}" y1="${padT}" x2="${padL}" y2="${h-padB}"></line><line class="axis-line" x1="${padL}" y1="${h-padB}" x2="${w-padR}" y2="${h-padB}"></line><line class="zero-line" x1="${padL}" y1="${zeroY.toFixed(1)}" x2="${w-padR}" y2="${zeroY.toFixed(1)}"></line>${bars}${valueLabels}${axis}${hits}</svg><div class="chart-legend">${legend}</div><p class="sub">时间段：${H(built.rangeText||`${S.start} 至 ${S.end}`)}；当前显示 ${M(series.length)} 个${kind==='month'?'月份':'日期'}。${H(built.note||'')}</p></div>`}
function trendPanel(kind){const metric=S.trendMetric;const needed=metric==='profit'?(String(S.q||'').trim()?'productProfit':'homeProfit'):metric==='traffic'?'homeTrafficDaily':metric==='inventory'?'inventoryTrend':'homeRankings';const built=buildTrendSeries(kind,metric);if(sourceLoading(needed,built.series))return`<section class="panel trend-panel"><h4>${kind==='month'?'月趋势':'日趋势'} · ${H(TREND_METRICS[metric]?.label||metric)}</h4><p class="sub">${H(SL[needed]||needed)} 加载中</p><div class="empty">正在加载${H(SL[needed]||needed)}，加载完成后自动刷新本图。</div></section>`;return`<section class="panel trend-panel"><h4>${kind==='month'?'月趋势':'日趋势'} · ${H(TREND_METRICS[metric]?.label||metric)}</h4><p class="sub">${H(metric==='inventory'?inventoryScopeNote():homeScopeSubtitle())}</p>${lineChart(kind,metric)}</section>`}

function auditHtml(){const a=D.audit;if(!a)return'<span class="audit-warn">未找到体检文件</span>';if(a.ok&&!a.warnings&&!a.errors)return'<span class="audit-ok">通过</span>';if(a.errors)return`<span class="audit-bad">${H(a.errors)} 个错误</span>`;return`<span class="audit-warn">${H(a.warnings||0)} 个提醒</span>`}
