function auditReasonsHtml(messages){const xs=A(messages).slice(0,4);if(!xs.length)return'';return`<small class="audit-reasons"><b>原因：</b>${xs.map(x=>`<i>${H(x)}</i>`).join('')}${A(messages).length>xs.length?`<i>另有 ${M(A(messages).length-xs.length)} 项，请到“系统状态”查看。</i>`:''}</small>`}
function healthItems(){const dates=D.dates||{};const costTs=dates.manualCostFileUpdatedAt||dates.manualCostUpdatedAt||dates.etStorageDetailUpdatedAt||dates.etStorageUpdatedAt||dates.manualStorageUpdatedAt||'';const salesTs=newestStamp(dates.salesUpdatedAt||dates.salesDate,LIVE_LAST_ORDER_AT);return[['BI 页面底稿',fmtStamp(genAt())],['销售数据更新',fmtStamp(salesTs)],['SHEIN 业务域',fmtStamp(dates.businessUpdatedAt||dates.businessDate)],['SHEIN 链接表现',fmtStamp(dates.linkUpdatedAt||dates.linkDate)],['成本表文件',fmtStamp(costTs)],['ET 货代仓',fmtStamp(dates.etUpdatedAt)],['数据体检',auditHtml(),auditMessages()]]}
