	function returnDetailTable(rows){return`<div class="table-wrap returns-table-wrap"><table class="returns-table"><colgroup><col class="c-time"><col class="c-store"><col class="c-order"><col class="c-product"><col class="c-num"><col class="c-status"><col class="c-status"><col class="c-reason"><col class="c-action"></colgroup><thead><tr><th>申请 / 创建</th><th>店铺</th><th>售后 / 订单</th><th>货号 / SKC</th><th class="num">涉及金额</th><th>退款结论</th><th>RTV/ET</th><th>原因</th><th>建议动作</th></tr></thead><tbody>${rows.map(r=>{const tip=dataTip([`售后单：${r.aftersales_order_no||'—'}`,`退货单：${r.return_order_no||'—'}`,`订单：${r.order_no||'—'}`,`申请时间：${fmtStamp(r.request_time)}`,`订单创建：${fmtStamp(r.order_create_time||r.order_created_date)}`,`付款：${r.payment_label||r.payment_method||'—'}`,`退款口径：${returnSettlementLabel(r)}`,`RTV：${returnRtvLabel(returnRtvKey(r))}`,r.rtv_trace_status?`RTV状态：${r.rtv_trace_status}`:'',r.et_return_order_ids?`ET退货单：${r.et_return_order_ids}`:'',r.destination_summary?`去向：${r.destination_summary}`:''].filter(Boolean).join('\n'));const openText=isOpenReturn(r)?`打开 ${M(N(r.open_days))} 天`:'';const orderNo=String(r.order_no||'').trim();const skcText=String(r.skc||r.sku||'').trim();const platformState=String(r.order_sub_status_name||r.return_package_status_name||returnStatusLabel(r)||'').trim();return`<tr><td><b>${H(shortDate(r.request_time||dt(r)))}</b><small>订单 ${H(shortDate(r.order_create_time||r.order_created_date||''))}</small></td><td>${H(storeDisplayName(sk(r)))}</td><td><b class="mono">${H(r.aftersales_order_no||r.return_order_no||'—')}</b><small class="mono return-order-line"><span>${H(orderNo||'—')}</span>${isCodReturn(r)?'<span class="cod-badge">COD</span>':''}</small></td><td><b>${H(prod(r))}</b><small class="mono return-skc">SKC ${H(skcText||'—')}</small></td><td class="num"><b>${M2(returnAmount(r))}</b><small>SAR · ${M(returnQty(r))} 件</small></td><td>${returnSettlementBadge(r)}<small>${H([openText,platformState].filter(Boolean).join(' · '))}</small></td><td data-tip="${tip}">${rtvBadge(r)}<small>${H([r.rtv_trace_status,r.et_return_order_ids,r.rtv_latest_received_time&&shortDate(r.rtv_latest_received_time)].filter(Boolean).join(' · ')||'无退货包裹/未匹配')}</small></td><td><b>${H(returnReasonTitle(r))}</b><small>${H(returnReasonSub(r)||'—')}</small></td><td><span class="note">${H(r.next_action||'结合排行复核。')}</span></td></tr>`}).join('')}</tbody></table></div>`}
function returnsPage(){ensure('returns',true);if(!A(D.afterSales).length&&SS.afterSales?.status!=='ok')return intro('退货退款中心','按售后申请时间和订单创建时间双口径拆解售后。')+wait('afterSales');
const scoped=returnScopeRows().slice().sort((a,b)=>String(b.request_time||dt(b)).localeCompare(String(a.request_time||dt(a))));const requestBase=returnDateRows(scoped,'request'),orderBase=returnDateRows(scoped,'order');const requestFiltered=requestBase.filter(returnFilterMatch),orderFiltered=orderBase.filter(returnFilterMatch);const primaryMode=S.returnsMode==='order'?'order':'request',primaryBase=primaryMode==='order'?orderBase:requestBase,filtered=(primaryMode==='order'?orderFiltered:requestFiltered).slice().sort((a,b)=>String(primaryMode==='order'?(b.order_create_time||b.order_created_date||b.request_time):(b.request_time||dt(b))).localeCompare(String(primaryMode==='order'?(a.order_create_time||a.order_created_date||a.request_time):(a.request_time||dt(a)))));const pageSize=Math.max(20,Math.min(500,Number(S.returnPageSize)||80)),totalPages=Math.max(1,Math.ceil(filtered.length/pageSize));S.returnPage=Math.min(Math.max(1,Number(S.returnPage)||1),totalPages);const start=(S.returnPage-1)*pageSize,rs=filtered.slice(start,start+pageSize);const cur=returnCounts(filtered),orderTop=returnCounts(orderFiltered);const salesBase=salesSummary(),sp=salesPaymentSummary();const avgOpenRows=orderFiltered.filter(isOpenReturn);const avgOpen=avgOpenRows.length?avgOpenRows.reduce((a,r)=>a+N(r.open_days),0)/avgOpenRows.length:0;const reasons=returnReasonOptions(primaryBase);const rtvWithTrace=orderFiltered.filter(r=>returnRtvKey(r)!=='not_applicable'&&returnRtvKey(r)!=='not_received').length;const primaryLabel=primaryMode==='order'?'订单创建口径':'售后申请口径';const rateDen=returnRateDenominator(sp);const rateOrders=returnOrderCount(orderFiltered);const rateDenOrders=N(rateDen.grossOrders);const orderReturnRate=ratio(rateOrders,rateDenOrders);const codOrderRows=orderBase.filter(r=>returnFilterMatchFor(r,'cod',S.returnReason,S.returnRtv));const codRateOrders=returnOrderCount(codOrderRows);const codRate=ratio(codRateOrders,sp.cod.grossOrders);const dataNote=`全局筛选作用域：${returnScopeText()}。顶部六个框固定按订单创建时间计算：${H(selectedRangeText())} 创建的${returnRateDenominatorLabel()}里，已发生售后的去重订单 ÷ 同期订单总数；其中退款已落定 ${M(orderTop.realizedCases)} 单 / ${M2(orderTop.realizedAmount)} SAR，退款待落定 ${M(orderTop.pendingCases)} 单 / ${M2(orderTop.pendingAmount)} SAR。待决金额只作风险提示，不会提前冲减净销量或已落定利润；下方当前明细为${primaryLabel}，命中 ${M(cur.cases)} 单 / ${M(cur.qty)} 件。`;
return intro('退货退款中心','售后不等于已经退款：已落定退款才冲减净销量；未落定申请单独显示为风险。日期仍按订单创建和售后申请两种口径查看。')+`<section class="kpis returns-kpis"><div class="stat"><div class="stat-label">售后涉及金额</div><div class="stat-value">${M2(orderTop.amount)}</div><div class="stat-note">退款待落定 ${M2(orderTop.pendingAmount)} SAR</div></div><div class="stat"><div class="stat-label">售后单 / 件数</div><div class="stat-value">${M(orderTop.cases)} / ${M(orderTop.qty)}</div><div class="stat-note">退款待落定 ${M(orderTop.pendingCases)} 单</div></div><div class="stat"><div class="stat-label">订单创建退货率</div><div class="stat-value">${PCT(orderReturnRate)}</div><div class="stat-note">${M(rateOrders)} / ${M(rateDenOrders)} 单 · ${returnRateDenominatorLabel()}</div></div><div class="stat"><div class="stat-label">未闭环</div><div class="stat-value">${M(orderTop.open)}</div><div class="stat-note">订单创建口径；平均打开 ${avgOpen?M2(avgOpen):'0'} 天</div></div><div class="stat"><div class="stat-label">COD 售后</div><div class="stat-value">${M(codRateOrders)}</div><div class="stat-note">同范围COD；退货率 ${PCT(codRate)}</div></div><div class="stat"><div class="stat-label">RTV 回仓</div><div class="stat-value">${M(orderTop.rtvReceived)}</div><div class="stat-note">订单创建口径；RTV线索 ${M(rtvWithTrace)}</div></div></section>${head('售后筛选与口径',dataNote,chips(['afterSales','homeRankings']))}<section class="panel returns-filter-panel"><div class="returns-scope-note"><b>这些筛选生效到哪里？</b><span>店铺/负责人、货号/订单搜索、状态、原因、RTV/COD 会同时影响本页 KPI、两组时间分析、排行和明细。顶部日期在“申请时间组”按售后申请日截取，在“订单创建组”按订单创建日截取；顶部六个框不跟随这两个按钮，只按订单创建口径计算。</span></div>${returnModeToggle(requestFiltered.length,orderFiltered.length)}${returnStatusTabs(primaryBase)}<div class="returns-filter-row"><label>原因 <select data-return-reason-select><option value="all">全部原因</option>${reasons.map(x=>`<option value="${H(x)}" ${S.returnReason===x?'selected':''}>${H(x)}</option>`).join('')}</select></label><label>RTV/ET <select data-return-rtv-select>${RETURN_RTV_FILTERS.map(([k,l])=>`<option value="${H(k)}" ${S.returnRtv===k?'selected':''}>${H(l)}</option>`).join('')}</select></label><button class="btn" data-return-clear="1">清空售后筛选</button><span class="note">点“退款待落定”可直接查看仍未最终退款的申请；这些单只列风险，不会提前扣减净销量。</span></div></section><section class="returns-time-stack">${returnTimeGroup(orderFiltered,'order',`A. ${H(selectedRangeText())} 创建的订单后续售后`,`这一组回答“这几天下的订单目前产生了哪些售后，以及售后分别在哪些天申请”。`,'按订单创建日','request','同一批订单的售后申请日')}${returnTimeGroup(requestFiltered,'request',`B. ${H(selectedRangeText())} 申请的售后单`,`这一组回答“这几天有哪些售后申请，以及这些单原本是什么时候创建的”。`,'按售后申请日','order','同一批售后的订单创建日')}</section>${returnRankCards(filtered)}<section class="panel returns-detail-panel"><h4>售后明细</h4><p class="sub">“退款已落定”会冲减净销量；“退款待落定”只作为风险小字展示，不提前改写真实收入。明细跟随当前口径：${H(primaryLabel)}。</p>${returnPager(S.returnPage,totalPages,filtered.length,pageSize)}${rs.length?returnDetailTable(rs):'<div class="empty">当前筛选没有售后记录。</div>'}${returnPager(S.returnPage,totalPages,filtered.length,pageSize)}</section>`}


const PRODUCT_PRIMARY_STATUSES=[['on','已上架'],['wait','待上架'],['sold','已售罄'],['off','已下架'],['no_link','缺覆盖']];
const PRODUCT_CELL_BADGE_LABEL={wait:'待上架',on:'已上架',sold:'已售罄',off:'已下架',no_link:'缺覆盖'};
const PRODUCT_STATUS_SHORT={on:'上',wait:'待',sold:'罄',off:'下',no_link:'缺'};
const PRODUCT_EXTRA_FILTERS=[['has_stock','有库存'],['no_stock','零库存'],['multi_on','多已上架'],['multi_link','链接总数多'],['has_sales','近30天有销量'],['has_activity','有活动/营销'],['wait_blocked','待上架卡点'],['missing_price','缺折后价']];
const PRODUCT_STATUS_FILTERS=[['all','全部覆盖状态'],...PRODUCT_PRIMARY_STATUSES,...PRODUCT_EXTRA_FILTERS];
function firstValue(r,fs){for(const f of fs){if(Object.prototype.hasOwnProperty.call(r||{},f)&&r?.[f]!=null&&r?.[f]!==''&&String(r?.[f]).toLowerCase()!=='null')return r[f]}return null}
function ensureProductStatusSet(){if(!(S.productStatusSet instanceof Set)){const vals=A(S.productStatusSet);S.productStatusSet=new Set(vals.length?vals:PRODUCT_PRIMARY_STATUSES.map(x=>x[0]))}if(!S.productStatusSet.size)PRODUCT_PRIMARY_STATUSES.forEach(([k])=>S.productStatusSet.add(k));return S.productStatusSet}
function productActiveStatuses(){return Array.from(ensureProductStatusSet())}
function productStatusLabelText(){const set=ensureProductStatusSet();const names=PRODUCT_STATUS_FILTERS.filter(([k])=>k!=='all'&&set.has(k)).map(([,l])=>l);const primaryAll=PRODUCT_PRIMARY_STATUSES.every(([k])=>set.has(k));const extraCount=PRODUCT_EXTRA_FILTERS.filter(([k])=>set.has(k)).length;if(primaryAll&&!extraCount)return'全部覆盖状态';return names.join('、')||'全部覆盖状态'}
function productSelectedStores(){const set=scopeStores();return stores.filter(x=>set.has(x)).sort(productStoreSort)}
function productSkcLikeQuery(q){const s=String(q||'').trim().toLowerCase();if(!s)return false;if(/^s[a-z]\d{4,}/.test(s))return true;return /^[a-z0-9-]{8,}$/i.test(s)&&/\d/.test(s)}
function productAliasSearchText(key){const map=CFG.productAliasSearch&&typeof CFG.productAliasSearch==='object'?CFG.productAliasSearch:{};return String(map?.[key]||'').toLowerCase()}
function productSearchOk(key,name='',row=null){if(!productValidKey(key))return false;const q=String(S.q||'').trim().toLowerCase();if(!q)return true;const short=/^[a-z0-9-]{1,4}$/i.test(q);const base=[key,name,row?.raw_goods_sn,row?.standard_goods_sn_list].map(x=>String(x||'').toLowerCase()).join('|');if(short)return base.includes(q)||productAliasSearchText(key).includes(q);if(base.includes(q)||productAliasSearchText(key).includes(q))return true;if(productSkcLikeQuery(q)){const skcText=[row?.skc,row?.spu,row?.sku_codes,row?.skuCodes,row?.skc_list,row?.best_skc,row?.sale_name,row?.product_name_cn].map(x=>String(x||'').toLowerCase()).join('|');if(skcText.includes(q))return true}return false}
function productScopeRows(rows){const set=scopeStores();return A(rows).filter(r=>{const st=sk(r);if(st&&!set.has(st))return false;if(!st&&S.scope!=='ALL')return false;return productSearchOk(pkey(r),prod(r),r)})}
function linkStatusKey(r){if(r?.status_virtual==='no_link')return'no_link';const st=String(r?.shelf_status_name||r?.health_bucket||'').trim();if(r?.is_on_shelf===true||/已上架/.test(st))return'on';if(r?.is_wait_shelf===true||/待上架/.test(st))return'wait';if(r?.is_sold_out===true||/已售罄|售罄/.test(st))return'sold';if(r?.is_out_shelf===true||/已下架|下架|淘汰|退役/.test(st))return'off';return'other'}
function linkStatusLabel(k){return({on:'已上架',wait:'待上架',sold:'已售罄',off:'已下架',no_link:'缺覆盖',other:'未识别'}[k]||k||'未识别')}
function productStatusBadge(k){const cls=k==='on'?'done':k==='wait'?'pending':k==='sold'?'platform_unclosed':k==='off'||k==='no_link'?'cancelled':'other';return`<span class="order-status ${H(cls)}">${H(linkStatusLabel(k))}</span>`}
function linkStockValue(r){const v=firstValue(r,['visible_usable_inventory','usable_inventory','platform_saleable_stock','platform_display_stock','stock_num','inventory_num','ivt_num','available_stock','saleable_stock']);return v==null?null:N(v)}
function linkDisplayStockValue(r){const v=firstValue(r,['visible_inventory_quantity','inventory_quantity','platform_display_stock','display_stock','inventory_num','ivt_num','total_stock']);return v==null?null:N(v)}
function priceRangeText(v){return String(v??'').trim().replace(/\s+/g,'').replace(/~/g,' ~ ')}
function priceRangeNumber(v){const m=String(v??'').match(/-?\d+(?:\.\d+)?/);return m?Number(m[0]):null}
function linkPriceValue(r){const p=linkMarketingMeta(r).active;return p?p.value:null}
function linkHasPlatformCurrentPrice(r){return priceRangeNumberStrict(r?.current_price_range_sar)!=null}
function linkCurrentPriceHasLead(r){return !!linkMarketingMeta(r).active}
function couponDiscountTextFromFields(factor,summary=''){const n=Number(factor);if(Number.isFinite(n)&&n>0&&n<=0.95){const off=Math.round((1-n)*100);return off>=5?`${off}%`:''}const m=String(summary||'').match(/(\d+(?:\.\d+)?)\s*%/);if(m){const off=Number(m[1]);return Number.isFinite(off)&&off>=5?`${m[1]}%`:''}return''}
function linkCouponBadgeText(r){const factor=firstValue(r,['marketing_coupon_factor','coupon_factor']);const summary=String(r?.marketing_coupon_summary||r?.coupon_summary||'').trim();const pct=couponDiscountTextFromFields(factor,summary);if(pct)return`${pct}券`;return /券|coupon/i.test(summary)&&!/(^|\D)(0|1)\s*%/.test(summary)?'券':''}
function linkMarketingPriceHasLead(r){return['marketing_suggested_ordinary_price_sar','marketing_limited_discount_price_sar','marketing_final_target_price_sar','marketing_ordinary_summary','marketing_activity_name'].some(k=>r?.[k]!=null&&r?.[k]!==''&&String(r?.[k]).toLowerCase()!=='null')}
function linkActivityText(r){return uniq([r?.activity_label,r?.performance_activity_tag,r?.performance_activity_names,r?.activity_names,r?.performance_official_operate_buttons,r?.performance_flow_diagnose_tabs].flatMap(x=>String(x||'').split(/\s*\/\s*|,|，/)).map(x=>x.trim()).filter(Boolean)).join(' / ')}
function linkTagList(r){const blocked=/^(已上架|待上架|已售罄|已下架|正常在售|下架候选|待上架卡点|缺覆盖|未知|无判断|营销中|即将开始|优化：.*|销量上涨|销量下滑|无变化)$/;return uniq([...(A(r?.skc_tags)),r?.skc_label,r?.inventory_goods_level,r?.inventory_goods_labels,r?.inventory_operate_labels,r?.inventory_rights_labels,r?.performance_new_goods_tag,r?.quality_grade].flatMap(x=>String(x||'').split(/\s*\/\s*|,|，|;|；/)).map(x=>x.trim()).filter(x=>x&&!['null','undefined','-','—'].includes(x.toLowerCase())&&!blocked.test(x)&&!/^(营销|活动|折扣|报名|限时|价格|券|下架候选)/.test(x)))}
function linkTagsText(r){return linkTagList(r).join(' / ')}
function productTagClass(tag){const t=String(tag||'');if(/备货款|高销|热销|B1|A1|A2/.test(t))return'good';if(/低点击|低转化|缺|异常|B2|C\d?/.test(t))return'warn';return'neutral'}
function productTagsHtml(r){if(r?.status_virtual==='no_link')return'<span class="note">无链接</span>';const tags=linkTagList(r);if(!tags.length)return'<span class="note">无</span>';const tip=dataTip(['平台标签：'+tags.join(' / '),r?.wait_shelf_block_reason?`待上架卡点：${r.wait_shelf_block_reason}`:'',r?.visible_inventory_date?`库存快照：${r.visible_inventory_date}`:''].filter(Boolean).join('\n'));const visible=tags.slice(0,4);const more=tags.length-visible.length;return`<span class="product-tags" data-tip="${tip}">${visible.map(t=>`<em class="${H(productTagClass(t))}">${H(t)}</em>`).join('')}${more>0?`<em class="more">+${M(more)}</em>`:''}</span>`}
function productGroupTagsHtml(rows){const tags=uniq(A(rows).flatMap(linkTagList));if(!tags.length)return'<div class="product-group-tags empty">平台标签：无</div>';const visible=tags.slice(0,8);const more=tags.length-visible.length;const tip=dataTip('平台标签汇总：'+tags.join(' / '));return`<div class="product-group-tags" data-tip="${tip}"><span>平台标签</span>${visible.map(t=>`<em class="${H(productTagClass(t))}">${H(t)}</em>`).join('')}${more>0?`<em class="more">+${M(more)}</em>`:''}</div>`}
function priceRangeNumberStrict(v){const n=priceRangeNumber(v);return n!=null&&Number.isFinite(n)&&n>0?n:null}
function priceRangeNumbers(v){return String(v??'').match(/-?\d+(?:\.\d+)?/g)?.map(Number).filter(n=>Number.isFinite(n)&&n>0)||[]}
function samePriceRange(a,b){const xs=priceRangeNumbers(a),ys=priceRangeNumbers(b);if(!xs.length||!ys.length)return false;return xs.length===ys.length&&xs.every((x,i)=>Math.abs(x-ys[i])<0.005)}
function platformCurrentLooksDiscounted(r){const cur=r?.current_price_range_sar;if(priceRangeNumberStrict(cur)==null)return false;const supply=r?.original_supply_price_range_sar||r?.purchase_price_range_sar||r?.list_price_range_sar;return !samePriceRange(cur,supply)}
function priceAnchorDate(){return dataAnchorDate()||isoDate(new Date())}
function priceWindowStatus(start,end,anchor=priceAnchorDate()){const a=ISO(anchor),s=ISO(start),e=ISO(end);if(s&&a&&a<s)return'future';if(e&&a&&a>e)return'expired';if(s||e)return'active';return'undated'}
function priceWindowLabel(status){return({active:'已生效',future:'未开始',expired:'已结束',undated:'无生效期'}[status]||status)}
