function inventorySupplyIssueKind(r){const rawGap=inventorySupplyGapValue(r),netGap=inventoryReconcileGapValue(r),costCover=inventoryCostCoverageGapValue(r);if(rawGap==null)return'unknown';if(rawGap<=0)return'none';if(costCover>0&&netGap<=Math.max(12,Math.ceil(rawGap*.05)))return'cost';if(netGap>0&&netGap<=20)return'loss';if(costCover>0)return'mixed';return'raw'}
function inventorySupplyEvidenceText(r){const gap=inventorySupplyGapValue(r),declared=inventoryDeclaredShipmentValue(r),cost=inventoryCostSupplyValue(r),net=inventoryReconcileGapValue(r),kind=inventorySupplyIssueKind(r);if(gap==null)return'当前库存未知，暂不做供销差异';if(gap>0){if(kind==='cost')return`成本表补充发货 ${M(cost)} · 损耗待核 ${M(net)}`;if(kind==='loss')return`损耗/破损待核 ${M(net)}`;if(kind==='mixed')return`成本表补充 ${M(inventoryCostCoverageGapValue(r))} · 仍待核 ${M(net)}`;return`库存/销量待核 ${M(gap)}`}if(declared>0&&cost>declared)return`ET有证据供给 ${M(declared)} · 成本表 ${M(cost)}`;if(declared>0)return'ET有发运/到仓证据累计';if(cost>0)return'成本表发货记录';return'无供给证据'}
