function inventoryRiskBadge(r,linkStats=new Map(),visibleMap=new Map()){const main=inventoryTagDefinitions(r).filter(t=>t.key!=='empty');const pending=inventoryPendingReviewValue(r)>0?`<span class="inventory-badge muted" data-tip="${dataTip('存在 ET 申请单，但缺少到仓/签收/有效在途证据，已从真实在途库存里剔除，只作人工复核。')}">缺证据 ${M(inventoryPendingReviewValue(r))}</span>`:'';return`<span class="inventory-tag-stack">${main.map(t=>`<span class="inventory-badge ${H(t.cls)}" data-tip="${dataTip(t.tip)}">${H(t.label)}</span>`).join('')||'<span class="inventory-badge muted">未发货</span>'}${pending}</span>`}
function inventoryMonthsText(r,includeIncoming=true){const v=includeIncoming?inventoryTotalMonthsValue(r):inventoryOnHandMonthsValue(r);return v==null?'—':`${M2(v)} 月`}
function inventoryMonthsHtml(r){const total=inventoryTotalMonthsValue(r),on=inventoryOnHandMonthsValue(r),daily=inventoryDailyValue(r),sold30=firstNum(r,['gross_sold_30d']);const tip=dataTip([`含在途去化周期：${total==null?'无速度':M2(total)+' 月'}`,`只看 ET可售：${on==null?'无速度':M2(on)+' 月'}`,`趋势日销：${M2(daily)} 件 = 近7天/7×30% + 近30天/30×70%`,`近7/30天实际销量：${M(firstNum(r,['gross_sold_7d']))} / ${M(sold30)}`,sold30<5?'低样本：近30天不足5件，趋势速度和去化周期波动较大。':''].filter(Boolean).join('\n'));return`<span class="inventory-months" data-tip="${tip}"><b>${total==null?'—':M2(total)} 月</b><small>可售 ${on==null?'—':M2(on)} 月</small></span>`}
function inventoryWarehouseText(r){const xs=uniq([r.et_loose_warehouses,r.et_box_warehouses].flatMap(x=>String(x||'').split(/\s*\/\s*|,|，/)).map(x=>x.trim()).filter(Boolean));return xs.length?xs.slice(0,2).join(' / '):'无 ET 仓位'}
function inventoryActionText(r,linkStat={},visible={}){const tags=inventoryTagDefinitions(r).map(x=>x.key);if(tags.includes('not_matched'))return'先补齐 ET 货号映射；当前库存未知，禁止按断货或零库存决策。';if(tags.includes('et_stale'))return'先刷新 ET 快照；过期库存不参与补货判断。';if(tags.includes('out')&&tags.includes('incoming'))return'ET可售已断，但有在途，重点跟进入仓。';if(tags.includes('out'))return'ET可售和在途都为 0；确认是否停卖或补货。';if(tags.includes('soon'))return'按当前加权去化速度，ET可售可能 30 天内耗尽。';if(tags.includes('incoming'))return'已有 ET 发货申请单未入仓。';if(tags.includes('stale'))return'ET有库存但近30天无销量，优先清货或暂停补货。';return'保持监控。'}
function inventoryPriorityCards(products,linkStats,visibleMap){return''}
function inventoryStoreCellRows(linkRows){const m=new Map();for(const r of A(linkRows)){if(!inventoryMatrixLinkOnShelf(r))continue;const key=[sk(r),inventoryProductKey(r)].join('|');if(!m.has(key))m.set(key,[]);m.get(key).push(r)}return m}
function inventoryStoreCell(p,store,cellRows){const rows=cellRows.get([store,inventoryProductKey(p)].join('|'))||[];if(!rows.length)return`<div class="cell inventory-store-cell no-link" data-tip="${dataTip([prod(p),storeDisplayName(store),'当前 OpenAPI 没有已上架链接库存'].join('\n'))}"><b>—</b></div>`;const saleableValues=rows.map(inventoryMatrixStockValue).filter(v=>v!=null),displayValues=rows.map(inventoryMatrixDisplayStockValue).filter(v=>v!=null),saleable=saleableValues.length?saleableValues.reduce((a,v)=>a+v,0):null,display=displayValues.length?displayValues.reduce((a,v)=>a+v,0):null,shown=saleable!=null?saleable:display,stockValues=rows.map(r=>inventoryMatrixStockValue(r)??inventoryMatrixDisplayStockValue(r)).filter(v=>v!=null),low=stockValues.filter(v=>v>0&&v<=5).length,zero=stockValues.filter(v=>v<=0).length;const cls=shown==null?'muted':zero?'zero':low?'low':'ok',label=shown==null?'—':M(shown),statusText=shown==null?'已上架库存字段暂缺':zero?'已上架断货':low?'已上架低库存':'已上架库存正常',fetchedAt=rows.map(r=>String(r.openapi_inventory_fetched_at||'')).sort().at(-1)||'';const tip=dataTip([prod(p),storeDisplayName(store),`状态：${statusText}`,`OpenAPI 可售库存：${saleable==null?'—':M(saleable)}`,`OpenAPI 总库存：${display==null?'—':M(display)}`,`已上架链接：${M(rows.length)}`,`库存读取：${fmtStamp(fetchedAt)}`,`低/零库存已上架链接：${M(low)} / ${M(zero)}`,`说明：这里只统计 OpenAPI 当前确认已上架的链接；待上架、售罄、已下架及过期快照不参与矩阵。`,`SKC：${uniq(rows.map(r=>r.skc||r.best_skc).filter(Boolean)).slice(0,12).join(' / ')||'—'}`].join('\n'));return`<div class="cell inventory-store-cell ${H(cls)}" data-tip="${tip}"><b>${label}</b></div>`}
function inventoryLegend(){return'<div class="inventory-legend"><span class="ok">已上架正常</span><span class="low">已上架低库存</span><span class="zero">已上架断货</span><span class="muted">已上架库存未知</span><span class="no-link">无已上架链接</span></div>'}
function inventoryProductMatrix(products,linkRows,linkStats=new Map()){const st=productSelectedStores(),cellRows=inventoryStoreCellRows(linkRows);const visible=products.slice().sort(inventoryDefaultCompare).slice(0,120);if(!visible.length)return'<div class="empty">当前筛选没有库存货号。</div>';return`${inventoryLegend()}<div class="inventory-matrix-wrap table-wrap"><div class="status-grid inventory-stock-grid" style="--cols:${st.length}"><div class="cell headcell product-head">标准货号<div class="tiny">ET / 虚拟</div></div><div class="cell headcell inventory-et-head" data-tip="${dataTip('ET实际可售库存：只在 ET 快照最新且已匹配时显示；未匹配或过期时为未知。')}">ET可售</div>${st.map(store=>`<div class="cell headcell store-head" data-tip="${dataTip(storeDisplayName(store))}">${H(store)}</div>`).join('')}${visible.map(p=>{const pk=inventoryProductKey(p),ls=linkStats.get(pk)||{},et=inventoryEtDisplay(p),total=inventorySupplyValue(p),front=ls.frontStockRows>0?N(ls.frontSaleable):null,frontText=inventoryVirtualQtyText(front),match=inventoryMatchStatus(p),etText=inventoryQtyText(et);const tip=dataTip([prod(p),`ET匹配：${match}`,`最新总库存：${inventoryQtyText(total)}`,`ET实际可售：${etText}`,`有效在途：${inventoryQtyText(inventoryIncomingValue(p))}`,`SHEIN已上架虚拟库存：${frontText}`,`近30销量：${M(firstNum(p,['gross_sold_30d']))}`,`去化周期：${inventoryMonthsText(p,true)}`].join('\n'));return`<div class="cell product inventory-product-cell" data-tip="${tip}"><b>${H(prod(p))}</b><div class="tiny">ET ${etText} · 虚拟 ${frontText}</div></div><div class="cell inventory-et-cell ${et===0?'zero':''}" data-tip="${tip}"><b>${etText}</b></div>`+st.map(store=>inventoryStoreCell(p,store,cellRows)).join('')}).join('')}</div></div><p class="foot">矩阵是本页唯一使用 SHEIN 虚拟库存的地方。店铺格只采用 45 分钟内的 OpenAPI 当前库存，并且只统计 OpenAPI 确认已上架的链接；待上架、售罄、已下架和过期快照一律不参与。ET 只有“已匹配且最新”才显示数值，未匹配或快照过期不会被当作 0 或断货。</p>`}
function inventorySupplyStack(r,ls={}){const gap=inventorySupplyGapValue(r),reconcile=inventoryReconcileGapValue(r),applications=firstNum(r,['et_ship_application_quantity']);const tip=dataTip([`最新总库存：${inventoryQtyText(inventorySupplyValue(r))}`,`其中 ET可售：${inventoryQtyText(inventoryEtValue(r))}`,`其中有效在途：${inventoryQtyText(inventoryIncomingValue(r))}`,inventoryPendingReviewValue(r)>0?`ET未闭环发货申请：${M(inventoryPendingReviewValue(r))}`:'',`ET申请数量：${M(applications)}`,`有发运/到仓证据累计：${M(inventoryDeclaredSupplyValue(r))}`,inventoryCostSupplyValue(r)>0?`成本表发货：${M(inventoryCostSupplyValue(r))}`:'',inventoryCostSupplyValue(r)>0?`成本表批次：${H(r.cost_batch_nos||'—')}`:'',gap!=null&&gap>0?`供销差异：${M(gap)}`:'',reconcile!=null&&reconcile>0?`补充成本表后剩余待核：${M(reconcile)}`:'',r.et_ship_status_summary?`ET状态：${r.et_ship_status_summary}`:'',`仓位：${inventoryWarehouseText(r)}`].filter(Boolean).join('\n'));return`<span class="inventory-supply-stack" data-tip="${tip}"><b>${inventoryQtyText(inventorySupplyValue(r))}</b><small>在库 ${inventoryQtyText(inventoryEtValue(r))} · 在途 ${inventoryQtyText(inventoryIncomingValue(r))}</small></span>`}
function inventoryLedgerRows(products){return products.filter(r=>inventoryHistorySupplyValue(r)>0||inventoryEtValue(r)>0||inventoryIncomingValue(r)>0||inventoryPendingReviewValue(r)>0).sort(inventoryCompareRows).slice(0,180)}
function inventoryProductLedger(products,linkStats,visibleMap){const rows=inventoryLedgerRows(products);if(!rows.length)return'<div class="empty">当前筛选没有 ET 库存货号；还没发过货的货号不列。</div>';return`<div class="table-wrap inventory-ledger-wrap"><table class="inventory-ledger"><colgroup><col class="c-product"><col class="c-risk"><col class="c-history"><col class="c-sold"><col class="c-et"><col class="c-incoming"><col class="c-monthly"><col class="c-depletion"><col class="c-storage"></colgroup><thead><tr><th>${inventorySortButton('product','标准货号')}</th><th>${inventorySortButton('tag','标签')}</th><th class="num">${inventorySortButton('history','有证据总供给')}</th><th class="num">${inventorySortButton('sold','总销量')}</th><th class="num">${inventorySortButton('et','在库')}</th><th class="num">${inventorySortButton('incoming','在途')}</th><th class="num">${inventorySortButton('monthly','预计月销')}</th><th class="num">${inventorySortButton('months','去化周期')}</th><th class="num">${inventorySortButton('storage','仓储费')}</th></tr></thead><tbody>${rows.map(r=>{const fee=inventoryStorageFee30d(r),monthly=inventoryMonthlyVelocity(r),gross30=firstNum(r,['gross_sold_30d']),rawGap=inventorySupplyGapValue(r),netGap=inventoryReconcileGapValue(r),cost=inventoryCostSupplyValue(r),declared=inventoryDeclaredSupplyValue(r),applications=firstNum(r,['et_ship_application_quantity']);const productTip=dataTip([prod(r),r.last_sale_date?`最近成交：${shortDate(r.last_sale_date)}`:'最近成交：无',r.et_ship_latest_application_date?`最近ET发货申请：${shortDate(r.et_ship_latest_application_date)}`:'最近ET发货申请：无',r.et_ship_latest_in_transit_date?`最近有效在途：${shortDate(r.et_ship_latest_in_transit_date)}`:'有效在途：无',r.et_ship_latest_pending_review_date?`最近ET未闭环申请：${shortDate(r.et_ship_latest_pending_review_date)}`:'',r.et_ship_latest_event_date?`最近ET节点：${shortDate(r.et_ship_latest_event_date)}`:'',`ET申请数量：${M(applications)}`,`有发运/到仓证据累计：${M(declared)}`,cost>0?`成本表发货：${M(cost)}（批次 ${H(r.cost_batch_nos||'—')}）`:'成本表发货：无',cost>0&&r.cost_latest_arrived_date?`成本表最近到仓：${shortDate(r.cost_latest_arrived_date)}`:'',rawGap!=null&&rawGap>0?`供销差异：ET可售 ${inventoryQtyText(inventoryEtValue(r))} + 有效在途 ${inventoryQtyText(inventoryIncomingValue(r))} + 历史销量 ${M(inventoryTotalSoldValue(r))} - 有证据供给 ${M(declared)} = ${M(rawGap)}`:'',rawGap!=null&&rawGap>0&&cost>declared?`成本表可解释：成本表发货 ${M(cost)}，补充后剩余 ${M(netGap)}；大额通常是非ET/特殊货代发货，小额常见为运输丢件、破损、报废或库存调整。`:'',netGap!=null&&netGap>0?`仍需核对：${M(netGap)} 件`:'',inventoryPendingReviewValue(r)>0?`ET未闭环发货申请数量：${M(inventoryPendingReviewValue(r))}`:''].filter(Boolean).join('\n'));const velocityNote=gross30<5?`低样本 · 近30天 ${M(gross30)} 件`:`近30天 ${M(gross30)} 件`;return`<tr><td data-tip="${productTip}"><b>${H(prod(r))}</b><small>${H(r.last_sale_date?'最近成交 '+shortDate(r.last_sale_date):'')}</small></td><td>${inventoryRiskBadge(r,linkStats,visibleMap)}<small>${H(inventoryWarehouseText(r))}</small></td><td class="num inventory-supply-cell"><b>${M(inventorySupplyEvidenceValue(r))}</b><small class="${rawGap!=null&&rawGap>0?'warn-text':''}">${H(inventorySupplyEvidenceText(r))}</small>${inventorySupplyEvidenceDetailHtml(r)}</td><td class="num"><b>${M(inventoryTotalSoldValue(r))}</b><small>历史毛销量</small></td><td class="num"><b>${inventoryQtyText(inventoryEtValue(r))}</b><small>ET可售</small></td><td class="num"><b>${inventoryQtyText(inventoryIncomingValue(r))}</b><small>${inventoryPendingReviewValue(r)>0?'ET未闭环 '+M(inventoryPendingReviewValue(r)):'有效在途'}</small></td><td class="num"><b>${M2(monthly)} 件/月</b><small>${H(velocityNote)}</small></td><td class="num">${inventoryMonthsHtml(r)}</td><td class="num"><b>${M2(fee)} SAR</b><small>${H(r.et_storage_fee_latest_date?'近30天至 '+shortDate(r.et_storage_fee_latest_date):'近30天')}</small></td></tr>`}).join('')}</tbody></table></div><p class="foot">“预计月销”是近7天日均×30%与近30天日均×70%的趋势速度，不是自然月实际销量；近30天不足5件时标记低样本。去化周期沿用同一趋势速度。“有证据总供给”只累计已有发运、物流、到仓或签收证据的 ET 数量，不再把仅创建/待审核的申请数量当作真实供给；申请总量仍保留在悬浮详情供核对。非 ET/特殊货代发货可由成本表作为辅助证据解释差异，但不会覆盖 ET 实盘库存。当前 ET 未匹配或快照过期时，在库和供销差异显示未知，不按 0 推断断货。</p>`}
function inventoryLowVisibleTable(rows){return'<div class="empty">低库存快照已隐藏：请使用店铺 × 标准货号已上架库存矩阵筛选虚拟库存问题。</div>'}
function inventoryLinkStockTable(linkRows=inventoryLinkRows()){return'<div class="empty">已上架链接库存明细已合并到矩阵，不再单独展示。</div>'}
function inventoryShipmentRows(){const q=String(S.q||'').trim().toLowerCase(),status=S.inventoryShipStatus||'open';return A(D.inventoryDepletion?.shipments).filter(r=>{if(status!=='all'&&String(r.shipment_group||'')!==status)return false;if(q){const hay=[pkey(r),prod(r),r.goods_title,r.ship_order_id,r.sku_code,r.barcode,r.ship_status_name,r.logistics_status_summary,r.box_status_summary].join('|').toLowerCase();if(!hay.includes(q))return false}return true})}
function inventoryShipmentSkuText(r){return uniq([r?.sku_code,r?.barcode].map(x=>String(x||'').trim()).filter(Boolean)).join(' · ')}
function inventoryShipmentWaybillHtml(r){const code=String(r?.waybill_code||'').trim();if(!code)return'';return`<small class="mono">${H(code)}</small>`}
function inventoryShipmentReviewReason(r){if(String(r?.shipment_group||'')!=='review')return'';const events=inventoryShipmentEvents(r),eta=r?.box_eta_time||r?.eta_end_date||'',now=new Date(),etaDate=eta?new Date(eta):null;const reasons=[];if(etaDate&&!Number.isNaN(+etaDate)&&etaDate<now)reasons.push('ETA已过');if(!events.length)reasons.push('无轨迹节点');if(!r?.shipment_departure_basis_time)reasons.push('未见发运');if(!r?.shipment_arrival_basis_time)reasons.push('未见到仓/签收');if(!reasons.length)reasons.push('缺少可用闭环证据');return reasons.join(' / ')}
function inventoryShipmentStatusHtml(r){const review=inventoryShipmentReviewReason(r);if(review)return`<span class="inventory-badge muted" data-tip="${dataTip('这里只列真正缺证据的 ET 发货申请单：没有到仓/签收证据，也不是有效在途。已有箱级到仓、收货或已完结证据的申请单会归到已到仓。')}">缺证据等你确认</span><small>${H(review)}</small>`;return`${H(r.ship_status_name||'—')}<small>ET状态 ${H(r.ship_status_code||'未知')}${r.has_arrival_evidence?' · 到仓证据':''}</small>`}
function inventoryShipmentDepartHtml(r){const depart=r.shipment_departure_basis_time||'';const tip=dataTip([depart?`确认发运：${fmtStamp(depart)}`:'确认发运：暂无证据',`创建：${fmtStamp(r.create_time)}`,`审核：${fmtStamp(r.check_time)}`,`国内仓入仓：${fmtStamp(r.domestic_warehouse_in_time)}`,`国内仓发出：${fmtStamp(r.domestic_warehouse_out_time)}`,r.etd_start_date?`ETD开始：${fmtStamp(r.etd_start_date)}`:''].filter(Boolean).join('\n'));return`<span class="inventory-ship-time" data-tip="${tip}"><b>${H(depart?shortDate(depart):'未确认')}</b><small>${depart?'确认发运':'仅申请/审核不算发运'}</small></span>`}
function inventoryShipmentArrivalHtml(r){const arrival=r.shipment_arrival_basis_time||r.overseas_warehouse_in_time||r.overseas_receipt_time||r.into_time||r.end_time;const eta=r.box_eta_time||r.eta_end_date||'';const tip=dataTip([`到仓口径：${fmtStamp(arrival)}`,`海外仓收货：${fmtStamp(r.overseas_receipt_time)}`,`海外仓入仓：${fmtStamp(r.overseas_warehouse_in_time)}`,`ETA：${fmtStamp(eta)||H(r.etd_eta||'—')}`,`订单入仓：${fmtStamp(r.into_time)}`,`结束：${fmtStamp(r.end_time)}`,r.remaining_time?`剩余：${r.remaining_time}`:'',r.etd_eta?`ETD/ETA原文：${r.etd_eta}`:''].filter(Boolean).join('\n'));return`<span class="inventory-ship-time" data-tip="${tip}"><b>${H(arrival?shortDate(arrival):(eta?shortDate(eta):'—'))}</b><small>${arrival?'到仓口径':'ETA'}</small></span>`}
function inventoryShipStatusTabs(rows){const all=A(D.inventoryDepletion?.shipments);const count=k=>k==='all'?all.length:all.filter(r=>String(r.shipment_group||'')===k).length;return`<div class="status-tabs inventory-ship-tabs">${[['open','在途/未入仓'],['review','缺证据等你确认'],['arrived','已到仓'],['all','全部发货单']].map(([k,label])=>`<button class="status-filter ${(S.inventoryShipStatus||'open')===k?'active':''}" data-inventory-ship-status="${H(k)}"><span>${H(label)}</span><b>${M(count(k))}</b></button>`).join('')}</div>`}
function inventoryShipmentEvents(r){const events=A(r?.tracking_events).filter(e=>e&&e.time);if(events.length)return events;const out=[];if(r?.etd_start_date)out.push({time:r.etd_start_date,location:'ETD',detail:'ETD 预计发运',kind:'etd'});if(r?.domestic_warehouse_in_time)out.push({time:r.domestic_warehouse_in_time,location:'国内仓',detail:'国内仓入仓',kind:'domestic_in'});if(r?.domestic_warehouse_out_time)out.push({time:r.domestic_warehouse_out_time,location:'国内仓',detail:['国内仓发出',r.logistics_status_summary].filter(Boolean).join(' · '),kind:'domestic_out'});const eta=r?.box_eta_time||r?.eta_end_date;if(eta)out.push({time:eta,location:r?.destination_city_summary||r?.storeroom_title||'海外仓',detail:'ETA 预计到仓',kind:'eta'});if(r?.overseas_receipt_time)out.push({time:r.overseas_receipt_time,location:r?.destination_storeroom_summary||r?.storeroom_title||'海外仓',detail:'海外仓收货',kind:'overseas_receipt'});if(r?.overseas_warehouse_in_time)out.push({time:r.overseas_warehouse_in_time,location:r?.destination_storeroom_summary||r?.storeroom_title||'海外仓',detail:'海外仓入仓',kind:'overseas_in'});return out}
function inventoryShipmentEventsText(r){return inventoryShipmentEvents(r).map(e=>`${fmtStamp(e.time)} · ${e.location||'—'} · ${e.detail||'—'}`).join('\n')}
function inventoryShipmentTimeHtml(r){const depart=r.shipment_departure_basis_time||r.domestic_warehouse_in_time||r.check_time||r.ship_time||r.create_time;const arrival=r.shipment_arrival_basis_time||r.overseas_warehouse_in_time||r.overseas_receipt_time||r.into_time||r.end_time;const eta=r.box_eta_time||r.eta_end_date||'';const tip=dataTip([`创建：${fmtStamp(r.create_time)}`,`审核：${fmtStamp(r.check_time)}`,`国内仓入仓：${fmtStamp(r.domestic_warehouse_in_time)}`,`国内仓发出：${fmtStamp(r.domestic_warehouse_out_time)}`,`发货口径：${fmtStamp(depart)}`,`ETA：${fmtStamp(eta)||H(r.etd_eta||'—')}`,`海外仓收货：${fmtStamp(r.overseas_receipt_time)}`,`海外仓入仓：${fmtStamp(r.overseas_warehouse_in_time)}`,`到仓口径：${fmtStamp(arrival)}`,`订单入仓：${fmtStamp(r.into_time)}`,`结束：${fmtStamp(r.end_time)}`,r.remaining_time?`剩余：${r.remaining_time}`:'',r.etd_eta?`ETD/ETA原文：${r.etd_eta}`:''].filter(Boolean).join('\n'));return`<span class="inventory-ship-time" data-tip="${tip}"><b>${H(shortDate(depart))}</b><small>发货口径</small><b>${H(arrival?shortDate(arrival):(eta?shortDate(eta):'—'))}</b><small>${arrival?'到仓口径':'ETA'}</small></span>`}
function inventoryShipmentTraceHtml(r){const events=inventoryShipmentEvents(r),eventText=inventoryShipmentEventsText(r);const first=events[0]||null,last=events.length?events[events.length-1]:null;const mid=events.find(e=>/customs|clearance|port|港|清关/i.test(String(e.detail||'')))||events[Math.floor(events.length/2)]||null;const visible=uniq([first,mid,last].filter(Boolean).map(e=>`${shortDate(e.time)} ${e.location||''} ${e.detail||''}`.replace(/\s+/g,' ').trim()));const route=first&&last?[first.location,last.location].filter(Boolean).join(' → '):'';const tip=dataTip([`运输方式：${r.transport_name_summary||r.transport_title||'—'}`,`目标仓：${r.destination_storeroom_summary||r.storeroom_title||'—'}`,`目的地：${r.destination_city_summary||'—'}`,`箱数：${M(r.et_box_event_count||r.all_box_number||r.send_box_count||r.case_number)} 个`,r.logistics_status_summary?`物流状态：${r.logistics_status_summary}`:'物流状态：—',r.box_status_summary?`箱状态：${r.box_status_summary}`:'箱状态：—',eventText?`完整轨迹（${M(events.length)} 节点）：\n${eventText}`:'完整轨迹：当前 ET 未下发节点，只能显示状态摘要。'].join('\n'));const main=visible.length?visible.join(' → '):(r.logistics_status_summary||r.box_status_summary||r.storeroom_title||'暂无箱级轨迹');const sub=events.length?`${route||'ET轨迹'} · ${M(events.length)} 节点`:(r.track_status_name||r.ship_status_name||'暂无完整节点');return`<span class="inventory-ship-trace" data-tip="${tip}"><b>${H(sub)}</b><small>${H(main)}</small></span>`}
function inventoryShipmentTable(){const rows=inventoryShipmentRows().slice(0,180);const all=A(D.inventoryDepletion?.shipments);if(!all.length)return'<div class="empty">云端暂未下发 ET 发货申请单明细；不会再用成本表冒充在途真相。</div>';if(!rows.length)return'<div class="empty">当前筛选没有 ET 发货申请单。</div>';return`<div class="inventory-ship-head">${inventoryShipStatusTabs(all)}</div><div class="table-wrap inventory-shipment-wrap"><table class="inventory-shipment-table"><thead><tr><th>发货申请单</th><th>货号 / SKU</th><th class="num">数量 / 箱数</th><th>状态</th><th>发货</th><th>到仓</th><th>运输 / 轨迹</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b class="mono">${H(r.ship_order_id||'—')}</b>${inventoryShipmentWaybillHtml(r)}</td><td><b>${H(prod(r))}</b><small>${H(inventoryShipmentSkuText(r))}</small></td><td class="num"><b>${M(r.quantity)}</b><small>${M(r.et_box_event_count||r.case_number||r.send_box_count||r.all_box_number)} 箱</small></td><td>${inventoryShipmentStatusHtml(r)}</td><td>${inventoryShipmentDepartHtml(r)}</td><td>${inventoryShipmentArrivalHtml(r)}</td><td>${inventoryShipmentTraceHtml(r)}</td></tr>`).join('')}</tbody></table></div><p class="foot">发货申请单来自 ET 后台：发货口径优先使用箱级“国内仓入仓时间”，到仓口径优先使用箱级“海外仓入仓/收货时间”或已完结/收货证据。状态 12 或有箱级到仓/收货/签收/已完结证据都归为已到仓；有发运、未过期 ETA 或物流证据但未到仓的归在途；只有缺到仓证据且不是有效在途的申请单才进“缺证据等你确认”。</p>`}
