function actionScopeRows(){const set=scopeStores(),all=S.scope==='ALL',q=String(S.q||'').trim().toLowerCase();return A(D.actions||[]).filter(r=>{const st=sk(r);if(st&&!set.has(st))return false;if(!st&&!all)return false;if(!q)return true;const short=/^[a-z0-9-]{1,4}$/i.test(q);const fields=[pkey(r),prod(r),r.skc,r.title,r.reason,r.evidence,r.next_step,r.category,r.action_domain];if(short)return fields.slice(0,4).join('|').toLowerCase().includes(q);return fields.join('|').toLowerCase().includes(q)})}
