function opsGlobalCapabilityBoundary(){const req=A(OPS.caps?.safety?.realSubmitRequires).join('、');const safe=OPS.caps?.safety?.safeWriteOperations||{},wl=OPS.caps?.safety?.realSubmitWhitelist||{};const gate=safe.enabled&&wl.enabled?'安全边界已开启':'安全边界仍在同步';return`<div class="ops-boundary"><div><b>${H(gate)}</b><span>不会静默修改 SHEIN</span></div><p>提交前必须完成账号权限、资料检查和对话确认；提交后继续回读结果。</p><small>${H(req||'账号、店铺权限、资料检查、对话确认、结果回读')}</small></div>`}
function opsTaskClass(t){const s=[t?.status,t?.lifecycle?.lifecycleStatus,t?.execution?.state].filter(Boolean).join('|');if(/done|submitted_readback_matched/.test(s))return'good';if(/blocked|failed|needs_manual_resolve|submitted_readback_failed|publish_pre_valid_failed/.test(s))return'bad';if(/confirmed|waiting|review|progress|executing|preflight_ready|submitted_but_readback_pending/.test(s))return'warn';return'muted'}
function opsApi(url,opt){return fetch(url,{cache:'no-store',headers:{'Content-Type':'application/json'},...(opt||{})}).then(async r=>{const j=await r.json().catch(()=>({ok:false,error:'Invalid JSON'}));if(!r.ok||j.ok===false)throw Error(j.error||('HTTP '+r.status));return j})}
