function scheduleOpsJobPoll(){if(OPS.jobPollTimer){clearTimeout(OPS.jobPollTimer);OPS.jobPollTimer=null}if(!opsActiveJobs().length)return;OPS.jobPollTimer=setTimeout(()=>{OPS.jobPollTimer=null;if(document.visibilityState==='visible')loadOpsRuntime(true,true).catch(()=>{});else scheduleOpsJobPoll()},1800)}
async function loadOpsRuntime(force=false,background=false){if(OPS.loading&&!force)return;if(!background){OPS.loading=true;OPS.error='';render()}try{const [caps,chats,jobs]=await Promise.all([opsApi('/api/openapi-capabilities'),opsApi('/api/link-ops-chats?limit=50'),opsApi('/api/link-ops-jobs?limit=80')]);OPS.caps=caps;OPS.chats=chats.data||chats;OPS.jobs=jobs;if(!S.opsActiveSessionId){const first=A(OPS.chats?.sessions)[0];if(first)S.opsActiveSessionId=String(first.id||'')}const sid=S.opsActiveSessionId&&S.opsActiveSessionId!=='__new__'&&!String(S.opsActiveSessionId).startsWith('pending_')?String(S.opsActiveSessionId):'';if(sid){const tasks=await opsApi(`/api/link-ops-tasks?limit=80&sessionId=${encodeURIComponent(sid)}`);OPS.tasks=tasks.data||tasks}else{OPS.tasks={version:1,updatedAt:null,tasks:[]}}OPS.syncedAt=new Date().toISOString();OPS.error=''}catch(e){OPS.error=e?.message||String(e)}finally{OPS.loading=false;scheduleOpsJobPoll();render()}}
function ensureOpsRuntime(){if(!OPS.caps&&!OPS.loading)loadOpsRuntime(true).catch(()=>{})}
function refreshOpsRuntime(){if(OPS.loading)return;opsSetBusy('refresh','','正在刷新会话、执行状态和店铺能力…');loadOpsRuntime(true).finally(()=>{opsSetBusy();render()}).catch(()=>{})}
