function opsMarkdownHtml(raw){const lines=String(raw||'').replaceAll(String.fromCharCode(13),'').split(String.fromCharCode(10));const out=[];let inCode=false,code=[],list=null,listTag='',quote=[],table=[];const flushList=()=>{if(list){out.push(`<${listTag}>${list.join('')}</${listTag}>`);list=null;listTag=''}};const flushQuote=()=>{if(quote.length){out.push(`<blockquote>${quote.map(x=>`<p>${opsMarkdownInline(x)}</p>`).join('')}</blockquote>`);quote=[]}};const flushTable=()=>{if(table.length){out.push(opsMarkdownTable(table));table=[]}};const flushBlocks=()=>{flushTable();flushQuote();flushList()};for(const line of lines){const trimmed=line.trim();if(trimmed.startsWith('```')){flushBlocks();if(inCode){out.push(`<pre><code>${H(code.join('\n'))}</code></pre>`);code=[];inCode=false}else{inCode=true;code=[]}continue}if(inCode){code.push(line);continue}if(!trimmed){flushBlocks();continue}if(/^[-*_]{3,}$/.test(trimmed)){flushBlocks();out.push('<hr>');continue}if(/^\|.+\|$/.test(trimmed)){flushQuote();flushList();table.push(trimmed);continue}flushTable();let m=trimmed.match(/^(#{1,3})\s+(.+)$/);if(m){flushQuote();flushList();const lv=Math.min(3,m[1].length);out.push(`<h${lv}>${opsMarkdownInline(m[2])}</h${lv}>`);continue}m=trimmed.match(/^>\s*(.+)$/);if(m){flushList();quote.push(m[1]);continue}m=line.match(/^\s*[-*+]\s+(.+)$/);if(m){flushQuote();if(listTag!=='ul'){flushList();list=[];listTag='ul'}list.push(`<li>${opsMarkdownInline(m[1])}</li>`);continue}m=line.match(/^\s*(?:\d+[.)、]|[一二三四五六七八九十]+、)\s*(.+)$/);if(m){flushQuote();if(listTag!=='ol'){flushList();list=[];listTag='ol'}list.push(`<li>${opsMarkdownInline(m[1])}</li>`);continue}flushBlocks();out.push(`<p>${opsMarkdownInline(trimmed)}</p>`)}flushBlocks();if(inCode)out.push(`<pre><code>${H(code.join('\n'))}</code></pre>`);return out.join('')||'<p></p>'}
function opsActiveSession(){if(S.opsActiveSessionId==='__new__')return null;if(OPS.pendingSession&&String(OPS.pendingSession.id||'')===String(S.opsActiveSessionId||''))return OPS.pendingSession;return A(OPS.chats?.sessions).find(s=>String(s.id||'')===String(S.opsActiveSessionId||''))||A(OPS.chats?.sessions)[0]||null}
