function render(){hideChartTip();shell();const view=$('view');if(S.tab!=='platform'&&S.core==='loading'){view.setAttribute('aria-busy','true');view.innerHTML='<div class="loading" role="status" aria-live="polite"><span class="spin" aria-hidden="true"></span><span>正在连接云端 BI runtime…</span></div>';enhanceAccessibility();return}if(S.tab!=='platform'&&S.core==='error'){view.setAttribute('aria-busy','false');view.innerHTML=`<div class="error" role="alert"><b>云端 BI runtime 连接失败</b><br>${H(S.err)}<p><button type="button" class="btn" id="retryCore">重试</button></p></div>`;enhanceAccessibility();return}const map={home,orders:ordersPage,returns:returnsPage,products:productsPage,inventory:inventoryPage,traffic:trafficPage,reviews:reviewsPage,marketing:marketingPage,platform:platformPage,ops:opsPage,system:systemPage};const ns=S.tab==='system'?Object.keys(SL):needsFor(S.tab);view.setAttribute('aria-busy','false');view.innerHTML=sectionFailureNotice(ns)+staleNotice(ns)+(map[S.tab]||home)();enhanceAccessibility();enhanceOpsWorkbench()}

