function setRangeDate(role,date){if(!date)return;if(role==='end'){S.end=date;S.calendarEndMonth=calendarMonthStart(date)}else{S.start=date;S.calendarStartMonth=calendarMonthStart(date)}if(S.start&&S.end&&S.start>S.end){const t=S.start;S.start=S.end;S.end=t}S.rangePreset='custom';S.rangeOpen=true;S.orderPage=1;S.returnPage=1;S.productPage=1;S.trafficPage=1;rerenderWithEnsure()}
function navigateTab(tab,{push=true}={}){const next=String(tab||'').replace(/^#/,'');if(!VALID_TABS.has(next))return;S.tab=next;const hash='#'+next;if(location.hash!==hash){if(push)history.pushState(null,'',hash);else history.replaceState(null,'',hash)}render();ensure(S.tab,true)}
