async function refreshLoginSessions(){const box=$('loginSessionBox');if(!box)return;box.innerHTML='<span class="pending">正在读取云端登录维护会话…</span>';try{const r=await fetch('/api/cloud-login/sessions',{cache:'no-store'});const j=await r.json().catch(()=>({ok:false,error:'Invalid JSON'}));if(!r.ok||j.ok===false)throw Error(j.error||('HTTP '+r.status));const raw=A(j.sessions);const sessions=raw.filter(s=>['starting','active'].includes(String(s?.status||''))||s?.alive?.xvfb||s?.alive?.websockify||s?.alive?.chrome);if(!sessions.length){box.innerHTML=`<div class="empty">当前没有临时登录窗口。历史已完成/已关闭会话 ${M(raw.length)} 条已隐藏；需要记录时打开完整维护中心。</div>`;return}box.innerHTML='<div class="login-session-list">'+sessions.map(s=>{const active=s.status==='active'||s.status==='starting';const cls=active?'active':s.status==='expired'?'expired':'idle';const open=active&&s.openUrl?`<a class="btn mini" href="${H(s.openUrl)}" target="_blank" rel="noreferrer">进入窗口</a>`:'';return`<div class="login-session-item ${H(cls)}"><b>${H(s.storeKey||'-')}</b><span>${H(s.status||'-')} · 到期 ${H(s.expiresAt||'-')}</span>${open}</div>`}).join('')+'</div>'}catch(e){box.innerHTML=`<div class="error"><b>读取登录会话失败</b><br>${H(e?.message||String(e))}<p><a class="btn" href="/cloud-login-maintenance" target="_blank" rel="noreferrer">打开完整维护中心</a></p></div>`}}
function chartTipEl(){let el=$('chartTooltip');if(!el){el=document.createElement('div');el.id='chartTooltip';el.className='chart-tooltip';document.body.appendChild(el)}return el}
function hideChartTip(){const el=$('chartTooltip');if(el)el.classList.remove('visible')}
function showChartTip(e,target){const text=target?.getAttribute('data-tip')||'';if(!text)return hideChartTip();const el=chartTipEl();el.textContent=text;const pad=14,w=260,h=120;let x=e.clientX+pad,y=e.clientY+pad;if(x+w>window.innerWidth)x=Math.max(12,e.clientX-w-pad);if(y+h>window.innerHeight)y=Math.max(12,e.clientY-h-pad);el.style.left=x+'px';el.style.top=y+'px';el.classList.add('visible')}
