document.addEventListener('keydown',e=>{if(e.target?.id==='opsChatInput'&&e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendOpsChat(false);return}if(e.target?.dataset?.orderPageInput!==undefined&&e.key==='Enter'){S.orderPage=Number(e.target.value)||1;render()}if(e.target?.dataset?.returnPageInput!==undefined&&e.key==='Enter'){S.returnPage=Number(e.target.value)||1;render()}if(e.target?.dataset?.productPageInput!==undefined&&e.key==='Enter'){S.productPage=Number(e.target.value)||1;render()}if(e.target?.dataset?.trafficPageInput!==undefined&&e.key==='Enter'){S.trafficPage=Number(e.target.value)||1;render()}if(e.target?.dataset?.marketingPageInput!==undefined&&e.key==='Enter'){S.marketingPage=Number(e.target.value)||1;render()}});
document.addEventListener('input',e=>{if(e.target?.id==='q'){S.q=e.target.value||'';S.orderPage=1;S.returnPage=1;S.productPage=1;S.productGroupLimit=40;S.trafficPage=1;S.marketingPage=1;render();ensure(S.tab,true);return}if(e.target?.id==='opsChatInput'){S.opsChatInput=e.target.value||'';const send=document.querySelector('[data-ops-send]');if(send)send.disabled=S.opsSending||!String(S.opsChatInput).trim();return}});
document.addEventListener('change',e=>{if(e.target?.id==='opsUploadFiles'){uploadOpsFiles(e.target.files);e.target.value='';return}if(e.target?.id==='scope'){S.scope=e.target.value||'ALL';S.orderPage=1;S.returnPage=1;S.productPage=1;S.productGroupLimit=40;S.trafficPage=1;S.marketingPage=1;render();ensure(S.tab,true);return}if(e.target?.dataset?.orderPageInput!==undefined){S.orderPage=Number(e.target.value)||1;render();return}if(e.target?.dataset?.orderPageSize!==undefined){S.orderPageSize=Number(e.target.value)||80;S.orderPage=1;render();return}if(e.target?.dataset?.returnPageInput!==undefined){S.returnPage=Number(e.target.value)||1;render();return}if(e.target?.dataset?.returnPageSize!==undefined){S.returnPageSize=Number(e.target.value)||80;S.returnPage=1;render();return}if(e.target?.dataset?.productPageInput!==undefined){S.productPage=Number(e.target.value)||1;render();return}if(e.target?.dataset?.productPageSize!==undefined){S.productPageSize=Number(e.target.value)||20;S.productPage=1;render();return}if(e.target?.dataset?.trafficPageInput!==undefined){S.trafficPage=Number(e.target.value)||1;render();return}if(e.target?.dataset?.trafficPageSize!==undefined){S.trafficPageSize=Number(e.target.value)||80;S.trafficPage=1;render();return}if(e.target?.dataset?.marketingPageInput!==undefined){S.marketingPage=Number(e.target.value)||1;render();return}if(e.target?.dataset?.marketingPageSize!==undefined){S.marketingPageSize=Number(e.target.value)||80;S.marketingPage=1;render();return}if(e.target?.dataset?.returnReasonSelect!==undefined){S.returnReason=e.target.value||'all';S.returnPage=1;render();return}if(e.target?.dataset?.returnRtvSelect!==undefined){S.returnRtv=e.target.value||'all';S.returnPage=1;render();return}if(e.target?.id==='rangeStart'){const d=ISO(e.target.value);if(d)setRangeDate('start',d);return}if(e.target?.id==='rangeEnd'){const d=ISO(e.target.value);if(d)setRangeDate('end',d);return}});
